const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_2","ls":"6.2","title":"Lernpfadübung · LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","version":"1.1","source":"Fachbereiche/BFSdual/LF06/LS_6_2_Sortiment_auswaehlen.md"};
const COMP=[["Fachkompetenz","Ich wähle ein gemeinsames Kernsortiment für beide Läden. Ich wähle passende Ergänzungen für jeden Laden. Ich begründe jeden Artikel mit Nachfragebelegen. Ich achte darauf, wie viel Platz da ist und ob die Waren lieferbar sind."],["Personalkompetenz","Ich prüfe, ob meine Lieblingsartikel auch zur Nachfrage passen."],["Sozialkompetenz","Ich erkläre meine Gründe im Team. Ich einige mich mit den anderen auf eine Auswahl."],["Methodenkompetenz","Ich prüfe die Liste mit den Angaben zur Nachfrage, zum Platz und zur Lieferung."],["Medienkompetenz","Ich finde im Katalog Angaben zu den Artikeln. Ich halte die Auswahl übersichtlich fest."]];
const BANK=[{"c":0,"title":"Ein gemeinsames Angebot","scene":"Global Bike kündigt für die Aktion vier Artikel an, die bei Block in Aurich und in der Bike Arena Oltmanns in Leer angeboten werden. Die Läden erhalten zusätzlich Artikel für ihre eigene Kundschaft.","ask":"Welche Aussagen treffen zu?","answer":[1,4],"options":["Die Bike Arena entscheidet allein, welche Artikel auch Block führt.","Die vier Artikel, die beide Läden anbieten, bilden das Kernsortiment.","Die vier gemeinsamen Artikel werden insgesamt auf beide Läden verteilt.","Jede örtliche Ergänzung muss automatisch in beiden Läden stehen.","Eine lokale Ergänzung deckt einen Bedarf in einem bestimmten Laden ab.","Die Zahl der gemeinsamen Artikel hängt allein vom jeweils größten Laden ab."],"why":"Vier gemeinsame Artikel stehen jeweils in beiden Läden. Die örtlichen Ergänzungen sind für den Bedarf am jeweiligen Standort gedacht.","hint":"Achte darauf, was ‚gemeinsam‘ für jeden einzelnen Laden heißt.","steps":"Zeichne je Laden eine Spalte. Markiere, welche Felder sich in beiden Spalten entsprechen.","example":"Sieht die Kundschaft denselben Artikel im gemeinsamen Angebot, muss er bei beiden Partnern erhältlich sein.","sourceRefs":["Handlungssituation","M3","M6"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Lieferbar zum Start?","scene":"Sebastian hat die K70-Klingel auf seine Liste gesetzt. Bei Block gibt es vier, bei der Bike Arena fünf Nennungen. Christian meldet, dass die Klingel frühestens in der Folgewoche kommt.","ask":"Welche Konsequenz passt zur geplanten Aktionswoche?","answer":[2],"options":["Nimm die Klingel auf, weil beide Läden sie nachgefragt haben.","Setze die Klingel in Block ein. Für fünf Nennungen in Leer wäre sie erst später nötig.","Lass die Klingel für diese Aktion weg und prüfe lieferbare Artikel.","Plane die Klingel an beiden Standorten ein und lasse ihren Platz bis zur Lieferung frei.","Führe sie als lokalen Artikel in Leer, damit Block den Liefertermin nicht abwarten muss.","Behandle sie als Ersatzartikel, der sicher noch vor Aktionsbeginn geliefert wird."],"why":"Die Nachfrage ist belegt, aber die Klingel ist beim geplanten Start nicht lieferbar. Deshalb passt sie nicht in die Sortimentsliste für diese Aktion.","hint":"Schau auf den Zeitraum, den die Aktion tatsächlich abdeckt.","steps":"Stell zwei Fragen getrennt: Wird der Artikel nachgefragt? Steht er rechtzeitig bereit?","example":"Ein passender Artikel kann für eine spätere Aktion vorgemerkt werden, wenn er jetzt nicht rechtzeitig kommt.","sourceRefs":["Handlungssituation","M1","M2"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Eine mögliche Sortimentslücke","scene":"Bei Block wurde elfmal Schutz für nasse Sättel angesprochen. In einem ersten Entwurf der Aktionsliste fehlt ein Artikel für diesen Zweck.","ask":"Welche Aussagen helfen bei der Prüfung?","answer":[0,3,5],"options":["Der Wunsch kann auf eine Lücke im vorgeschlagenen Aktionssortiment hinweisen.","Elf Nennungen beweisen, dass Block allgemein keinen passenden Artikel führt.","Eine Lücke liegt vor, wenn ein Artikel im Katalog steht, aber noch niemand danach fragt.","Ein Sattelüberzug kann genau den festgehaltenen Wunsch aufgreifen.","Jede nicht ausgewählte Artikelgruppe ist automatisch eine Sortimentslücke.","Ob die Lücke im regulären Ladenangebot besteht, geht aus der Aktionsliste allein nicht hervor."],"why":"Eine Sortimentslücke verbindet einen belegten Wunsch mit einem fehlenden passenden Angebot. Der Entwurf sagt nur etwas über die Aktion, nicht über das gesamte gewöhnliche Sortiment.","hint":"Prüfe Bedarf und vorhandenes Angebot getrennt.","steps":"Vergleiche die Nachfrage mit der geplanten Auswahl. Gib an, auf welches Sortiment sich deine Aussage bezieht.","example":"Fehlt ein Pumpenmodell, kann trotzdem ein passender Pumpentyp angeboten werden. Dann fehlt nicht zwingend eine Lösung für den Bedarf.","sourceRefs":["M1","M2","M5","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Nennungen verstehen","scene":"Eine Person fragt im Beratungsgespräch nach einem Licht und einem Schloss. Das Personal hält beide Wünsche fest.","ask":"Welche Aussagen treffen auf die Nachfrageübersicht in LS 6.2 zu?","answer":[1,2,5],"options":["Für jede Person darf in der Übersicht nur ein Wunsch erscheinen.","Ein Gespräch kann zwei Nennungen erzeugen.","Die Beratungstagebücher liefern Daten zu Fragen und Wünschen.","Aus zwei Nennungen folgen zwei abgeschlossene Käufe.","Die Zahl aller Nennungen entspricht automatisch der Zahl aller beratenen Personen.","Wenn du Nennungen vergleichst, beschreibe sie als Wünsche, nicht als Personen."],"why":"Die Übersicht zählt geäußerte Wünsche. In einem Gespräch kann mehr als ein Wunsch vorkommen. Die Zahlen sind weder Personen- noch Verkaufszahlen.","hint":"Was ist in dieser Übersicht die Zähleinheit?","steps":"Prüfe je Aussage, ob von Wünschen, Personen oder Käufen die Rede ist.","example":"Eine Person kann auf derselben Einkaufstour nach zwei verschiedenen Artikeln fragen, ohne einen zu kaufen.","sourceRefs":["M1","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Artikel im Katalog finden","scene":"Im Katalog stehen T30 Rahmentasche, R40 Sattelüberzug, P50 Minipumpe und F60 Flaschenhalter. Die Kennung kommt ins Ergebnisblatt.","ask":"Welche Kombinationen sind korrekt?","answer":[0,4],"options":["P50 kennzeichnet die Minipumpe.","R40 kennzeichnet die Rahmentasche.","F60 kennzeichnet das LED-Lichtset.","Ein Katalogcode nennt die Zahl der Nennungen in beiden Läden.","T30 kennzeichnet die Rahmentasche.","Die Kennung ist überflüssig, wenn jeder Artikel einen Platz braucht."],"why":"Mit P50 und T30 sind die Minipumpe und die Rahmentasche eindeutig identifizierbar. Ein Code verrät keine Kundenzahl oder Platzbelegung.","hint":"Lies Name und Kennung in derselben Katalogzeile.","steps":"Vergleiche vollständige Kennungen, auch wenn mehrere Artikel ähnlich heißen.","example":"Wenn eine Ware eindeutig mit Artikelcode und Namen in der Liste steht, kann Jan sie leicht im Katalog wiederfinden.","sourceRefs":["M2","M5","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Katalogzeile vollständig lesen","scene":"Eine Gruppe möchte die Minipumpe P50 einplanen. Laut Katalog ist sie zum Start lieferbar, belegt einen Platz und passt auf zwei gängige Ventilarten, die auf dem Artikel stehen.","ask":"Welche Angaben kannst du korrekt ins Ergebnisblatt übernehmen?","answer":[1,2,4],"options":["Die Pumpe passt auf jede Ventilart.","P50 belegt pro Laden einen Aktionsplatz.","P50 ist laut Katalog zum Start lieferbar.","P50 ist der Flaschenhalter.","Vor dem Kauf lassen sich die passenden Ventilarten am Artikel ablesen.","Die Zahl der nachgefragten Pumpen steht in der Spalte ‚Platzbedarf‘."],"why":"Der Katalog zeigt Kennung, Eignungsmerkmale, Lieferbarkeit und Platzbedarf. Zwei gängige Typen sind keine Zusage für jedes Ventil.","hint":"Trenne beschriebenes Merkmal, Lieferdatum und Platzbedarf.","steps":"Übernimm nur die Angaben, die in derselben Produktzeile stehen.","example":"Die Aussage ‚für zwei gängige Ventilarten‘ lässt sich nicht ohne weiteren Beleg zu ‚universell passend‘ erweitern.","sourceRefs":["M2","M5"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Plätze richtig zählen","scene":"Block hat fünf Aktionsplätze; die Bike Arena hat sechs. Jeder Artikel braucht genau einen Platz je Laden. Der siebte Stellplatz in Leer gehört zum eigenen Sortiment des Ladens.","ask":"Welche Platzplanung entspricht den Vorgaben?","answer":[0,3,5],"options":["Die vier gemeinsamen Artikel belegen je vier Plätze in Aurich und Leer.","Aus fünf und sechs Plätzen folgen elf unterschiedliche Aktionsartikel.","Die Bike Arena hat sieben Plätze für die Global-Bike-Aktion.","Bei Block bleibt nach dem Kernsortiment genau ein Platz für einen lokalen Artikel.","Die vier gemeinsamen Artikel belegen in den beiden Läden zusammen genau vier Plätze.","In Leer bleiben nach dem Kernsortiment zwei Aktionsplätze für lokale Artikel."],"why":"Ein gemeinsamer Artikel belegt einen Platz in jedem Laden. Damit bleiben bei Block 5 − 4 = 1 und bei der Bike Arena 6 − 4 = 2 Plätze für die Ergänzungen.","hint":"Rechne die Plätze für jeden Laden einzeln.","steps":"Zieh die vier gemeinsamen Plätze von fünf und von sechs ab. Der siebte Platz in Leer gehört nicht zur Aktion.","example":"Zwei Läden, die je drei gemeinsame Produkte zeigen, brauchen dafür sechs belegte Stellplätze.","sourceRefs":["M2","M3"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Warengruppen und Sortimentsbreite","scene":"Das Sortiment enthält ein Lichtset, zwei verschiedene Schlösser und eine Rahmentasche. Alle Produkte haben je eine eigene Artikelkennung.","ask":"Welche Aussagen treffen fachlich zu?","answer":[1,4],"options":["Die Sortimentsbreite beträgt vier Warengruppen, weil es vier Artikelcodes gibt.","Beleuchtung, Schlösser und Taschen bilden hier drei Warengruppen.","Ein zweites Schloss schafft automatisch eine neue Warengruppe.","Die Sortimentsbreite beschreibt, wie viele Exemplare der Händler liefern kann.","Ein zusätzliches Produkt derselben Warengruppe vergrößert nicht automatisch die Sortimentsbreite.","Vier belegte Aktionsplätze bedeuten immer vier verschiedene Warengruppen."],"why":"Die Sortimentsbreite zählt verschiedene Warengruppen. Zwei Schlossmodelle belegen zwei Artikelpositionen, gehören aber derselben Warengruppe an.","hint":"Sortiere nach Warenart statt nach Anzahl der Artikelnummern.","steps":"Ordne zuerst jeden Artikel einer Gruppe zu. Zähle dann nur die unterschiedlichen Gruppen.","example":"Zwei Lampen können zwei Plätze beanspruchen und trotzdem zur einen Warengruppe Beleuchtung gehören.","sourceRefs":["M3","M6"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Eigene Vorlieben überprüfen","scene":"Du würdest selbst das Multitool W90 kaufen. Im Beratungstagebuch stehen zum Nachziehen von Schrauben fünf Nennungen bei Block und acht in der Bike Arena.","ask":"Welche Überlegungen sind hilfreich?","answer":[0,3],"options":["Ich halte fest, dass meine Vorliebe eine erste Idee und noch kein Beleg ist.","Ich nehme W90 in beide Läden, weil ich das Werkzeug selbst gebrauchen kann.","Ich nehme W90 aus der Planung, weil eigene Vorlieben grundsätzlich nie passen.","Ich vergleiche die Nennungen für W90 mit den Belegen für andere Artikel je Laden.","Acht Nennungen beweisen, dass W90 in Leer häufiger verkauft wird als die Minipumpe.","Ich brauche die Platzprüfung nicht mehr, sobald ich einen Nachfragebeleg finde."],"why":"Die Nachfrage stützt W90 grundsätzlich. Ob es den begrenzten Platz bekommt, hängt vom Vergleich mit anderen Bedarfen und von seiner Rolle im Sortiment ab.","hint":"Wo endet deine eigene Erfahrung und wo beginnt der überprüfbare Fallbeleg?","steps":"Trenne persönliche Vorliebe, beobachteten Bedarf und spätere Auswahlentscheidung.","example":"Ein Produkt kann gut sein und trotzdem für einen knappen Aktionsplatz gegen ein anderes verlieren.","sourceRefs":["M1","M2","M3"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Sich im Team verständigen","scene":"Im Team möchte eine Person den Sattelüberzug R40 für Block. Eine zweite Person möchte dort den einen lokalen Platz für ein Reflektorband B80 nutzen.","ask":"Welche Beiträge helfen bei der Einigung?","answer":[1,3,4],"options":["Wir verteilen den einen Platz gleichzeitig an beide Artikel.","Ich frage beide nach dem Bedarf, den ihr Vorschlag erfüllt.","Ich setze zuerst meine Idee durch und suche danach einen Grund.","Wir prüfen die Nennungen zu Sattelschutz und zusätzlicher Sichtbarkeit in Aurich.","Wir entscheiden mit Belegen und halten den Grund für den Verzicht fest.","Die Zahl der Nennungen in Leer entscheidet allein über beide Vorschläge in Aurich."],"why":"Beide Vorschläge können sinnvoll sein. Die Nachfrage im betroffenen Laden und die verfügbare Fläche helfen, eine gemeinsame, nachvollziehbare Wahl zu treffen.","hint":"Klärt, worin sich der Nutzen der beiden Vorschläge unterscheidet.","steps":"Vergleicht beide Artikel anhand derselben Kriterien und erklärt den Grund für eure Entscheidung.","example":"Ein Artikel mit geringerem Bedarf kann trotzdem sinnvoll sein, wenn er eine wichtige Lücke schließt. Dafür braucht ihr eine konkrete Begründung.","sourceRefs":["M1","M2","M3","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Mit beiden Läden sprechen","scene":"Block betont Zubehör für den Arbeitsweg. In Leer fragen Familien nach Zubehör fürs Trinken und für Pannen. Sebastian soll Entscheidungen beiden Partnern erklären können.","ask":"Welche Gesprächsbeiträge unterstützen den Vergleich?","answer":[0,2,5],"options":["Fasse je Laden einen konkreten Bedarf aus der Sortimentsrunde zusammen.","Frage nur den größeren Laden, weil er mehr Plätze hat.","Frage nach, ob ein gemeinsamer Artikel den Zweck an beiden Standorten erfüllen kann.","Versprich jedem Laden alle Artikel seiner Wunschliste.","Besprich nur Artikelcodes, damit die Gründe keine Rolle spielen.","Erkläre, warum ein örtlich besonders gut passender Artikel eine lokale Ergänzung sein kann."],"why":"Die Empfehlungen richten sich an beide Läden. Ein gemeinsamer Bedarf kann in den gemeinsamen Kern führen. Ein besonders lokaler Bedarf kann eine Ergänzung begründen.","hint":"Höre auf die unterschiedlichen Kaufanlässe.","steps":"Prüfe zuerst Gemeinsamkeiten und dann die Gründe für Unterschiede. Formuliere je Laden eine kurze Rückfrage.","example":"Zwei Geschäfte können beide Licht brauchen, aber bei Regenschutz oder Trinkpausen unterschiedliche Schwerpunkte setzen.","sourceRefs":["Handlungssituation","M1","M4"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Eine schwache Zahl richtig bewerten","scene":"In Leer wurde Schutz für nasse Sättel viermal angesprochen. Die Beobachtungen erwähnen zwei nasse Wochenenden.","ask":"Welche Schlussfolgerungen sind tragfähig?","answer":[2,4],"options":["Vier bedeutet, dass der Bedarf in Leer überhaupt nicht vorkommt.","Der Bedarf ist garantiert das ganze Jahr gleich hoch.","Das Wetter kann einen Teil der Beobachtung erklären.","Block muss den Sattelüberzug ebenfalls weglassen, weil die Zahl in Leer niedriger ist.","Prüfe die vier Nennungen zusammen mit den anderen Ursachen und Artikelwünschen.","Vier Nennungen zählen als exakt vier sicher verkaufte Sattelüberzüge."],"why":"Auch vier Nennungen sind ein Bedarfssignal. Die nassen Wochenenden helfen, es in den richtigen Zusammenhang zu stellen. Mehr als die vorliegenden Beobachtungen ist nicht belegt.","hint":"Eine niedrige Zahl ist kein Nullwert.","steps":"Schau neben die Tabelle: Welche Beobachtung zeigt, wann dieser Wunsch in Leer vorkam?","example":"Eine Regenwoche kann die Zahl der Fragen nach Regenschutz vorübergehend erhöhen.","sourceRefs":["M1"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Einen Kernartikel belegen","scene":"Für einen gemeinsamen Platz stehen L10 LED-Lichtset und R40 Sattelüberzug zur Diskussion. Für Licht bei Dunkelheit stehen 13 Nennungen bei Block und 8 in Leer. Für Sattelschutz sind es 11 und 4. Beide Artikel sind lieferbar.","ask":"Welche Folgerungen tragen die Angaben?","answer":[0,2,4],"options":["L10 lässt sich mit einem vergleichsweise starken Bedarf in beiden Läden begründen.","R40 ist automatisch der beste gemeinsame Artikel, weil elf mehr als acht sind.","Die Zahlen sprechen dafür, R40 besonders als Ergänzung bei Block zu prüfen.","Kein Artikel kann zum Kern gehören, wenn die Nennungszahlen in den Läden unterschiedlich sind.","Für L10 sollten im Ergebnisblatt die Belege beider Standorte stehen.","Wenn beide Artikel lieferbar sind, spielt die Nachfrage für den gemeinsamen Kern keine Rolle mehr."],"why":"Für einen Kernartikel zählen beide Standorte. L10 hat in beiden Läden einen deutlichen Beleg. Der Bedarf für R40 ist in Aurich stärker und kann eine örtliche Ergänzung begründen.","hint":"Vergleiche pro Artikel seine beiden Standortwerte.","steps":"Vergleiche erst Licht mit Sattelschutz je Laden. Prüfe danach, für welchen Bereich der jeweilige Artikel nachvollziehbar wäre.","example":"Zwei gute lokale Werte aus unterschiedlichen Zeilen können nicht zu einem Beleg für denselben Artikel zusammengezählt werden.","sourceRefs":["M1","M2","M3","M5"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Lokalen Artikel für Aurich auswählen","scene":"Für den letzten Platz bei Block sind R40 Sattelüberzug und F60 Flaschenhalter lieferbar. R40 hat 11 Nennungen in Aurich; F60 hat 4. Laut Beobachtung stehen Räder dort tagsüber häufig draußen.","ask":"Welche Empfehlung nutzt die stärkeren Belege für genau diesen Platz?","answer":[3],"options":["F60 für Aurich, weil 13 Nennungen aus Leer auch für Aurich zählen.","F60 und R40 für Aurich, weil beide im Lager verfügbar sind.","Keinen Artikel, da für die Aktion ausschließlich das Kernsortiment zugelassen ist.","R40 für Aurich, weil dort mehr Leute nach Sattelschutz fragen und viele Räder draußen stehen.","F60 für Aurich, weil der Katalog die Gewindeösen am Rahmen erwähnt.","R40 zusätzlich in beiden Läden, auch wenn dann der gemeinsame Kern größer als vier wäre."],"why":"R40 passt zum beschriebenen lokalen Bedarf und belegt genau den freien Platz. Die höhere Nachfrage für F60 in Leer ist kein Grund, ihn in Aurich vorzuziehen.","hint":"Welche Kundschaft nutzt den letzten Platz?","steps":"Vergleiche die zwei Werte in der Spalte ‚Block, Aurich‘ und prüfe die Fallbeobachtung zu Pendelnden.","example":"Eine lokale Ergänzung kann bei einem Laden gut passen, auch wenn die andere Kundschaft wenig danach fragt.","sourceRefs":["M1","M2","M3"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Zwei lokale Plätze in Leer","scene":"Die gemeinsame Liste enthält bereits L10, S20, T30 und W90. Für Leer stehen P50, F60, B80 und R40 zur Wahl. Alle sind zum Start lieferbar. Ihre Nennungen vor Ort sind 12, 13, 10 und 4.","ask":"Welche Aussagen tragen eine begründete Empfehlung auf Basis der beiden häufigsten noch offenen Wünsche?","answer":[0,3],"options":["F60 greift die häufigste offene Nachfrage nach Trinkzubehör in Leer auf.","R40 muss wegen der elf Nennungen in Aurich vor F60 in Leer gewählt werden.","W90 kann in Leer zusätzlich zum bereits besetzten Kernplatz noch als örtliche Ergänzung eingetragen werden.","P50 greift mit zwölf Nennungen einen starken Bedarf für unterwegs in Leer auf.","Vier noch verfügbare Artikel bedeuten vier zusätzliche Plätze.","B80 ist wegen der zehn Nennungen nicht lieferbar."],"why":"Die beiden häufigsten noch unbesetzten Wünsche in Leer passen zu F60 und P50. W90 ist schon im gemeinsamen Kern. B80 bleibt eine lieferbare, aber niedriger priorisierte Alternative.","hint":"Beachte sowohl die Nachfrage als auch die Artikel, die schon im Kern stehen.","steps":"Ordne die vier offenen Wünsche nach ihren Nennungen in Leer. Wähle die zwei höchsten für die zwei örtlichen Plätze.","example":"Ein Artikel, der schon in beiden Läden steht, braucht keine weitere Aktionszeile als örtliche Ergänzung.","sourceRefs":["M1","M2","M3","M5"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Einen Listenfehler finden","scene":"Ein Entwurf nennt L10, S20, T30 und R40 als gemeinsamen Kern. Bei Block steht R40 nochmals als lokale Ergänzung. Für Leer stehen P50, F60 und B80 zusätzlich in der Liste.","ask":"Welche Prüfergebnisse sind korrekt?","answer":[1,3,4],"options":["Die Liste ist korrekt, weil alle sieben genannten Artikelkennungen im Katalog stehen.","R40 kann nicht zugleich gemeinsamer und nur in Aurich angebotener Artikel sein.","Leer kann seine sieben Plätze allesamt für Global Bike verwenden.","Leer hat drei örtliche Ergänzungen eingeplant, zugelassen sind zwei.","Die vier Kernartikel müssen nicht neu verteilt werden, nur weil die lokalen Zeilen korrigiert werden.","Sechs Nennungen für B80 in Aurich reichen aus, um den siebten Aktionsplatz in Leer freizugeben."],"why":"R40 ist schon im gemeinsamen Sortiment und darf nicht als örtliche Ergänzung doppelt geführt werden. Leer hat einen örtlichen Artikel zu viel. Die vier Kernplätze sind formal korrekt gefüllt.","hint":"Prüfe zunächst doppelte Kennungen und dann freie Plätze pro Laden.","steps":"Markiere den vierzeiligen Kern und die lokalen Zeilen. Prüfe jede Kennung und rechne die Plätze getrennt.","example":"Ein Artikel, der einen Platz belegt, kann nicht zwei verschiedene vereinbarte Auswahlpositionen gleichzeitig erfüllen.","sourceRefs":["M2","M3","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":3,"title":"Kern und Plätze nachrechnen","scene":"Die Liste ist so geplant: gemeinsamer Kern L10, S20, T30 und B80. Block ergänzt R40. Die Bike Arena ergänzt P50 und F60. Alle sieben Kennungen sind verschieden.","ask":"Welche Ergebnisse stimmen nach der Platzprüfung?","answer":[0,2,4,5],"options":["Block belegt fünf von fünf Aktionsplätzen.","Leer belegt sieben von sechs Aktionsplätzen.","Leer belegt sechs von sechs Aktionsplätzen.","Die Gesamtzahl elf belegter Plätze bedeutet, dass elf verschiedene Artikel ausgewählt wurden.","Die vier Kernartikel belegen über beide Läden zusammen acht Plätze.","Sieben verschiedene Kennungen stehen in der Liste."],"why":"Die vier Kernartikel stehen in beiden Läden und belegen zusammen acht Plätze. Drei lokale Artikel füllen die übrigen Plätze. Es sind elf Stellplätze für sieben verschiedene Artikel.","hint":"Unterscheide die Zahl der Artikelkennungen von der Zahl aller belegten Plätze.","steps":"Zähle in Aurich 4 + 1, in Leer 4 + 2 und im Ergebnisblatt 4 + 1 + 2 Kennungen.","example":"Ein gemeinsamer Artikel zählt einmal als Produkt, aber in zwei Läden als zwei belegte Plätze.","sourceRefs":["M2","M3","M5"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Einen lieferbaren Artikel weglassen","scene":"Ihr nutzt in Leer die zwei örtlichen Plätze für P50 und F60. Sie knüpfen an zwölf und dreizehn Nennungen an. Das lieferbare B80 hat dort zehn Nennungen und steht auch nicht im Kern.","ask":"Welche Formulierungen begründen den Verzicht angemessen?","answer":[1,4],"options":["B80 ist nicht lieferbar.","B80 wurde in Leer nachgefragt. Die zwei örtlichen Plätze gehen aber an die im Fall häufiger genannten Pumpen und Flaschenhalter.","Zehn Nennungen spielen für die Entscheidung keine Rolle, wenn die anderen Artikel mehr haben.","B80 wird in Leer nie nachgefragt und wäre deswegen generell ungeeignet.","Die Wahl für P50 und F60 greift die beschriebenen Bedürfnisse für Pannen und Trinkpausen auf. B80 bleibt eine mögliche Alternative.","B80 wird weggelassen, weil B80 der Katalogcode für eine Klingel ist."],"why":"Eine gute Begründung erkennt den Bedarf für B80 an und nennt, warum die anderen passenden Artikel die knappen Plätze bekommen. Verfügbarkeit bleibt dabei eine getrennte Frage.","hint":"Sag zuerst, warum B80 grundsätzlich infrage kommt.","steps":"Nenne danach einen überprüfbaren Unterschied, der P50 und F60 in dieser Auswahl Vorrang gibt.","example":"‚Lieferbar und passend, aber wegen knapper Plätze nachrangig‘ ist belastbarer als ‚nicht gebraucht‘.","sourceRefs":["M1","M2","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":1,"title":"Bei neuen Belegen umdenken","scene":"Übungsvariante: Du wolltest W90 als örtlichen Artikel für Leer. Das Team hat W90 inzwischen in den vier gemeinsamen Kernartikeln vorgesehen. F60 ist noch nicht berücksichtigt.","ask":"Welche Reaktionen sind sinnvoll?","answer":[0,2,4],"options":["Ich prüfe, welchen offenen Kundenwunsch die örtliche Ergänzung zusätzlich erfüllen kann.","Ich halte am Multitool fest, ohne die übrige Auswahl anzusehen.","Ich stelle F60 und W90 anhand der Nennungen in Leer und des bestehenden Angebots gegenüber.","Ich streiche F60 allein deshalb, weil es nicht meine erste Wahl war.","Ich erkläre dem Team, welche Angabe meine ursprüngliche Wahl verändert hat.","Ich nehme F60 zusätzlich zu allen geplanten Artikeln auf, ohne Plätze nachzurechnen."],"why":"Das Kernsortiment kann einen Bedarf bereits abdecken. Für die örtliche Ergänzung zählen offene Kaufanlässe und die Platzgrenze. Die Begründung zeigt, warum du deine erste Idee angepasst hast.","hint":"Vergleiche nicht nur die beiden Produkte. Schau auch auf die vollständige Liste.","steps":"Markiere die Bedarfe, die bereits abgedeckt sind. Prüfe die Nennungen zum Bedarf, der noch offen ist.","example":"Wenn die Auswahl schon ein passendes Werkzeug enthält, kann ein örtlicher Platz einen anderen Bedarf abdecken.","sourceRefs":["M1","M2","M3","M5"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Einen fairen Vergleich moderieren","scene":"Für den letzten gemeinsamen Platz diskutiert ihr B80 und W90. Beide Artikel sind lieferbar. Sichtbarkeit wurde sechsmal in Aurich und zehnmal in Leer genannt. Schrauben nachziehen wurde fünfmal in Aurich und achtmal in Leer genannt.","ask":"Welche Beiträge sind für eine fachliche Einigung hilfreich?","answer":[1,2,5],"options":["B80 gewinnt, weil sein Code alphabetisch vor W90 steht.","Wir vergleichen die beiden Angaben je Laden und nennen die Kaufanlässe dazu.","Wir prüfen, ob der bisherige Kern einen der Bedarfe bereits gut abdeckt.","Wir teilen den letzten Kernplatz auf und zeigen B80 nur in einem Laden und W90 nur im anderen.","Wir lassen den anderen Vorschlag ungehört, weil wir uns beeilen müssen.","Wir notieren im Ergebnisblatt, warum die gewählte Lösung für beide Läden passt."],"why":"Die Nennungen, der vorhandene Kern und die Aufgabe eines gemeinsamen Artikels liefern Vergleichskriterien. Ein geteilter Platz mit verschiedenen Artikeln wäre keine gemeinsame Position.","hint":"Ein gemeinsamer Artikel muss als solcher in beiden Läden vertreten sein.","steps":"Hört beide Gründe an. Prüft je Laden die Daten und entscheidet dann für dieselbe Position in beiden Listen.","example":"Bei knappen Plätzen hilft ein transparenter Grund auch dann, wenn beide Ideen sinnvoll sind.","sourceRefs":["M1","M2","M3","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":2,"title":"Rückmeldung auf eine Sortimentsliste","scene":"Eine andere Gruppe schreibt: ‚Wir empfehlen F60 in Leer, weil der Flaschenhalter angesagt ist. Block bekommt R40, weil die Kundschaft das möchte.‘","ask":"Welche Rückmeldungen machen die Liste besser?","answer":[0,3,5],"options":["Belegt F60 mit den 13 Nennungen zum Trinkzubehör in Leer.","Verwendet mehr Artikelbezeichnungen, damit der Bedarf unklar bleiben darf.","Entfernt alle Zahlen, weil ein Hinweis auf Nachfrage für die Prüfung reicht.","Ergänzt zu R40 die elf Nennungen in Aurich und den Hinweis auf draußen abgestellte Räder.","Führt F60 grundsätzlich in beiden Läden, damit ihr keine Gründe mehr angeben müsst.","Weist für beide Artikel aus, dass sie zum Start lieferbar sind und je einen Platz belegen."],"why":"Konkrete Nennungen und eine Fallbeobachtung begründen die örtliche Auswahl. Lieferbarkeit und Platzbedarf machen den Vorschlag umsetzbar und prüfbar.","hint":"Welche Ausdrücke kann Jan nachprüfen und welche bleiben vage?","steps":"Schlage pro Artikel einen konkreten Nachfragebeleg aus der richtigen Laden-Spalte vor. Ergänze die Prüfdaten aus dem Katalog.","example":"‚Wurde oft genannt‘ erklärt wenig. ‚13 Nennungen zum Trinkzubehör in Leer‘ kann man nachlesen.","sourceRefs":["M1","M2","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Ein Ergebnisblatt vervollständigen","scene":"Im Ergebnisblatt steht: ‚Minipumpe für Bike Arena.‘ Die Pumpe soll eine lokale Sortimentsergänzung sein. Im Katalog heißt sie P50, sie ist lieferbar und braucht einen Platz. In Leer gibt es zwölf Nennungen zum Aufpumpen unterwegs.","ask":"Welche Angaben sind passend für die Zeile?","answer":[0,1,3,5],"options":["P50 Minipumpe als eindeutige Kennung und Bezeichnung.","Lokale Ergänzung, Bike Arena Oltmanns, Leer.","Gemeinsamer Kern, beide Läden, Beleg nur aus Aurich.","Leer: 12 Nennungen zum Aufpumpen unterwegs.","Nicht lieferbar, weil es im gemeinsamen Kern nur vier Plätze gibt.","Zum Start lieferbar laut M2, ein Platz in Leer."],"why":"Die Zeile nennt den Artikel eindeutig, weist seinen Standort aus und verbindet die Auswahl mit einem Nachfragebeleg und den Katalogangaben.","hint":"Denk aus Sicht von Jan: Kann er die Zeile verstehen und überprüfen?","steps":"Ordne Kennung, Bereich, Laden, Beleg und Lieferbarkeit den Feldern des Ergebnisblatts zu.","example":"‚F60, lokal, Leer, 13 Nennungen für Trinkzubehör, zum Start lieferbar‘ wäre nach demselben Muster prüfbar.","sourceRefs":["M1","M2","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":4,"title":"Ein Planungstool prüfen","scene":"Ihr habt eine digitale Tabelle angelegt. Für jeden der vier gemeinsamen Artikel steht ein gesetztes Häkchen in der Spalte ‚Block‘ und eine leere Zelle in ‚Bike Arena‘. Die Summe für den Kern in Leer zeigt dadurch null.","ask":"Welche Korrekturen sind fachlich sinnvoll?","answer":[1,3,4],"options":["Lasst die leeren Felder. Kernartikel zählen nur an einem der beiden Standorte.","Kennzeichnet jeden der vier gemeinsamen Artikel auch in der Spalte ‚Bike Arena‘.","Fügt stattdessen vier neue örtliche Artikel für Leer hinzu.","Prüft, dass die Summenformel Kern und örtliche Ergänzung je Standort mitzählt.","Haltet im Ergebnis fest, dass der Plan für Block fünf und für Leer sechs Plätze hat.","Addiert die beiden verfügbaren Platzanzahlen und verzichtet auf die Einzelsummen."],"why":"Alle Kernartikel gehören in beide Standortspalten. Die getrennten Summen zeigen, ob die Auswahl an jedem Standort in die vier gemeinsamen und die örtlichen Plätze passt.","hint":"Ist eine leere Zelle eine fachliche Aussage oder hier ein Eingabefehler?","steps":"Kontrolliere erst die Eintragung der Kernartikel, dann die Formel und zuletzt die Sollwerte je Laden.","example":"Eine rechnerisch korrekte Summe kann fachlich falsch sein, wenn die zugrunde liegenden Markierungen unvollständig sind.","sourceRefs":["M3","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Einen Gesamtvorschlag freigeben","scene":"Jan vergleicht zwei Entwürfe. A nennt L10, S20, T30 und B80 im Kern, R40 für Block, P50 und F60 für Leer. B ist gleich aufgebaut, ersetzt aber B80 im Kern durch K70. Beide Läden haben Interesse an einer Klingel gemeldet; sie kommt erst in der Folgewoche.","ask":"Welche Aussagen sind für die Freigabe richtig?","answer":[0,2,5],"options":["Entwurf A kann die Platz- und Lieferbedingungen der Aktionswoche erfüllen, wenn die Auswahl fachlich begründet wird.","Entwurf B passt, da Interesse an der Klingel die fehlende Lieferbarkeit ausgleicht.","Entwurf B hätte einen Artikel, der an beiden Standorten zum Start fehlt.","Entwurf A darf nur deshalb freigegeben werden, weil die Zahl der Artikelcodes stimmt.","Bei Entwurf A reicht ein Nachfragebeleg aus einem beliebigen Laden für den gesamten Kern.","Für Entwurf A lässt sich W90 als lieferbare, nicht ausgewählte Alternative diskutieren."],"why":"Entwurf A erfüllt mit lieferbaren Artikeln die Form der Liste. Die Auswahl braucht zusätzlich Nachfragebelege. In B fehlt ein gemeinsamer Artikel beim Start. W90 ist ein Beispiel für einen lieferbaren Artikel, dessen Auslassung ihr begründen könnt.","hint":"Prüfe jeden Entwurf in derselben Reihenfolge.","steps":"Zähle die Plätze. Prüfe dann Lieferbarkeit und Nachfrage je Artikel. Wähle zum Schluss einen sinnvollen Vergleichsartikel.","example":"Ein Entwurf mit richtigen Zeilenzahlen kann an einer einzigen fehlenden Lieferung scheitern.","sourceRefs":["M1","M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"c":0,"title":"Die Liste neu angehen","scene":"Übungsvariante: Jan bittet dich, Sebastians vorläufige Liste für beide Läden zu überprüfen. Beide Läden haben Anfragen zur K70 erhalten. Die Lieferung kommt aber erst in der Folgewoche.","ask":"Womit beginnst du die Überarbeitung?","options":["Ich vergleiche für jeden Artikel die Nachfrage und den Lieferstatus aus den Unterlagen.","Ich kläre mit den Ladenvertretungen, welcher Wunsch hinter der Nachfrage nach der Klingel steckt.","Ich notiere vor der Auswahl die Frist, die vier gemeinsamen Plätze und die lokalen Platzgrenzen.","Ich markiere den Nachweis zum verspäteten Artikel und stelle die Nachfrage zu lieferbaren Gruppen daneben.","Ich frage Christian nach dem Artikeleintrag und bespreche mit Sebastian, welche Kundenwünsche er den Läden erklären muss.","Ich trenne die Artikel, die für diese Woche freigegeben werden können, von den Vorschlägen für spätere Aktionen."],"consequences":["Du findest Unterschiede zwischen belegtem Bedarf und verfügbarer Ware.","Du kannst bei der Auswahl die Gründe der Läden berücksichtigen.","Du startest mit den Bedingungen, die die Liste erfüllen muss.","Die Änderung lässt sich am Katalog und an der Nachfrage begründen.","Christian und Sebastian wissen, welche Informationen sie zur Überarbeitung beitragen.","Eine spätere Lieferung kann den Aktionsplan dieser Woche nicht versehentlich bestimmen."],"sourceRefs":["Handlungssituation","M1","M2","M3"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":24,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"c":3,"title":"Vier gemeinsame Plätze besetzen","scene":"Übungsvariante: Der Klingelplatz wird neu besetzt. Für den gemeinsamen Kern werden mehrere lieferbare Artikel diskutiert. Die Händler wollen vier Artikel gemeinsam bewerben.","ask":"Wie machst du die Kandidaten für die gemeinsame Auswahl vergleichbar?","options":["Ich stelle je Artikel die beiden Nachfragewerte nebeneinander und halte ihre Bedeutung fest.","Ich bitte beide Läden, zu den Kandidaten je eine typische Kundenanfrage zu erläutern.","Ich lege ein Raster mit genau vier gemeinsamen Feldern an und prüfe lieferbare Kandidaten für beide Standorte.","Ich verknüpfe für jeden möglichen Kernartikel die Katalogzeile mit den Bedarfshinweisen beider Standorte.","Ich kläre mit beiden Vertretungen, welche Artikel sie in derselben Werbung gut vertreten können.","Ich kontrolliere, dass jeder Kernartikel zum Start verfügbar ist und pro Laden einen Platz belegt, bevor ich Vorschläge vergleiche."],"consequences":["Die Standortvergleiche sind mit denselben Angaben belegbar.","Die Gründe beider Läden fließen in die gemeinsame Auswahl ein.","Die Form der gemeinsamen Ankündigung wird von Beginn an eingehalten.","Jan kann das Katalogmerkmal und seine Nachfragebegründung zusammen nachlesen.","Ein gemeinsamer Vorschlag hat die Kaufanlässe beider Standorte im Blick.","Die Kandidaten erfüllen dieselben Mindestbedingungen."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":25,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":0,"title":"Die Ergänzung für Block auswählen","scene":"Übungsvariante: Der Kern steht vorläufig. Beim letzten Platz in Aurich sind der Sattelüberzug und das Reflektorband noch offen. Beide sind lieferbar. Die Rückmeldung aus dem Laden verweist auf draußen abgestellte Räder.","ask":"Wie kommst du zu einer begründeten Auswahl für Aurich?","options":["Ich stelle die elf Nennungen zum Sattelschutz den sechs zur zusätzlichen Sichtbarkeit gegenüber und beziehe die Beobachtung ein.","Ich frage Block, welches Problem beim täglichen Arbeitsweg durch den zusätzlichen Artikel gelöst werden soll.","Ich prüfe, welcher der beiden Artikel noch nicht im Kern steht und den einen Platz sinnvoll ergänzen kann.","Ich verknüpfe die Kundenanfragen, die Alltagssituation und die Katalogmerkmale der beiden Produkte.","Ich bitte die Fachkraft bei Block, die beiden Bedarfe aus einem typischen Beratungsgespräch zu vergleichen.","Ich kontrolliere, dass der Entwurf genau eine lokale Zeile für Block enthält und beide Kandidaten zum Start verfügbar sind."],"consequences":["Der gewählte Bedarf lässt sich mit Zahl und Fallbeobachtung nachvollziehen.","Du berücksichtigst, was der örtliche Laden mit dem zusätzlichen Platz erreichen will.","Deine Ergänzung kann im vorgesehenen Rahmen umgesetzt werden.","Die Entscheidung bleibt überprüfbar, auch wenn Jan eine Rückfrage stellt.","Die Perspektive der Beratung schärft den Vergleich der Kandidaten.","Du schließt Doppelbelegungen und nicht umsetzbare Vorschläge aus."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":26,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":2,"title":"Die Ergänzungen für Leer abgleichen","scene":"Übungsvariante: Für Leer sind Flaschenhalter, Minipumpe und Reflektorband im Gespräch, soweit sie im Entwurf noch nicht eingeplant sind. Platz ist für zwei örtliche Artikel. Die Bike Arena möchte die Familienausflüge unterstützen.","ask":"Wie führst du deine Empfehlung für Leer fort?","options":["Ich vergleiche die drei Nachfragewerte und erläutere, welche Wünsche die zwei vorgeschlagenen Artikel abdecken.","Ich kläre mit dem Laden, welche zwei Schwierigkeiten Familien bei ihren Ausflügen am häufigsten schildern.","Ich kontrolliere die zwei lokalen Plätze und prüfe, ob eine Kennung bereits im Kern oder in Aurich vergeben ist.","Ich halte zu jedem Kandidaten fest, welche Beobachtung seine Bedeutung in Leer bestätigt.","Ich bitte die Ladenvertretung um eine kurze Rückmeldung zu unserer Begründung für die beiden örtlichen Artikel.","Ich gleiche die Kandidaten mit dem Lieferstatus ab und streiche jede Variante, die mehr als zwei örtliche Plätze braucht."],"consequences":["Deine Auswahl und der Verzicht lassen sich mit Daten erklären.","Die Empfehlung berücksichtigt die Erfahrung in Leer.","Du bewahrst die vereinbarte Platzverteilung.","Der Vergleich bleibt auf konkrete Beobachtungen vor Ort bezogen.","Am Ergebnis ist erkennbar, welche Rückfrage des Ladens noch offen sein könnte.","Du begrenzt die Liste auf umsetzbare Vorschläge."],"sourceRefs":["M1","M2","M3","M4"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":27,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":4,"title":"Das Ergebnisblatt prüfen","scene":"Übungsvariante: Euer Entwurf enthält vier gemeinsame und drei örtliche Positionen. Jan möchte auch einen lieferbaren Artikel sehen, den ihr bewusst ausgelassen habt.","ask":"Wie machst du die Liste für die Freigabe prüfbar?","options":["Ich prüfe pro Zeile die Kennung, den konkreten Nachfragebeleg und den nachgewiesenen Verzichtsgrund.","Ich lasse je eine Person die Perspektive von Block und der Bike Arena prüfen und Rückfragen aufschreiben.","Ich prüfe vor der Freigabe die separaten Summen, den Lieferstatus und den für das eigene Sortiment reservierten siebten Platz in Leer.","Ich ergänze zum ausgelassenen lieferbaren Artikel, welche anderen Bedarfe im direkten Vergleich Vorrang hatten.","Ich bitte Sebastian, die Auswahl kurz aus Sicht beider Handelspartner zu erklären, und verbessere eine unklare Begründung.","Ich kennzeichne, welche Positionen zur Aktion gehören, und dokumentiere den Platz- und Liefercheck."],"consequences":["Der Nachweis reicht vom Produkt bis zum Grund für den Verzicht.","Deine Liste geht auf typische Rückfragen beider Geschäfte ein.","Die Freigabe beruht auf den tatsächlich nutzbaren Plätzen und verfügbaren Artikeln.","Der Verzicht bleibt auch für eine dritte Person nachvollziehbar.","Sebastian kann beide Empfehlungen mit euren dokumentierten Gründen vertreten.","Das Ergebnisblatt enthält die für den Vertrieb nötigen Prüfmerkmale."],"sourceRefs":["M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":28,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"c":1,"title":"Empfehlung im Gespräch vertreten","scene":"Übungsvariante: Jan bietet dir eine Minute für den Abschluss. Er fragt, warum K70 nicht in der Aktion steht und welcher andere Eintrag zeigt, dass ihr die Nachfrage berücksichtigt habt.","ask":"Wie schließt du deinen Weg ab?","options":["Ich erkläre die Liefergrenze von K70 und zeige mit einer konkreten Zahl, wie ein ausgewählter Artikel einen Kundenwunsch trifft.","Ich beantworte die Klingelfrage und erkläre anhand der Rückmeldungen aus den Läden, warum die vereinbarte Liste für beide passt.","Ich fasse die Freigabebedingungen zusammen und zeige an den Platzsummen, dass die Liste umsetzbar ist.","Ich zeige den Katalogbeleg zu K70 und eine vollständig begründete Zeile im Ergebnisblatt.","Ich sage, welche Rückfrage aus dem Team oder aus einem Laden unsere Auswahl verändert hat, und erkläre die Auslassung von K70.","Ich trenne die aktuelle Liste von der späteren Klingeloption und sage, wer eine neue Lieferprüfung veranlassen kann."],"consequences":["Jan kann den Verzicht und die ausgewählte Alternative anhand konkreter Angaben prüfen.","Die Beteiligten erkennen ihre Kaufanlässe und die Liefergrenze in der Empfehlung.","Jan sieht, ob die endgültige Liste die Vorgaben für die Aktion erfüllt.","Katalog und Ergebnisblatt tragen deine kurze Erklärung.","In der Begründung ist sichtbar, wie die Mitarbeit anderer die Entscheidung verbessert hat.","Die Aktionsliste bleibt verlässlich und die spätere Entscheidung ist eindeutig zugeordnet."],"sourceRefs":["Handlungssituation","M1","M2","M3","M5"],"hint":"Überlege, welche Perspektive du bisher für die Empfehlung genutzt hast.","steps":"Lies die neue Information. Wähle, wie du sie mit deinem bisherigen Schwerpunkt verbindest.","example":"Eine Änderung im Plan kann am besten über einen neuen Beleg, eine Rückfrage oder die Prüfung einer Vorgabe erklärt werden.","why":"Die Rückmeldung zeigt, wie deine sechs Entscheidungen zusammenpassen.","id":29,"l":3,"type":"story","caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Kern oder Ergänzung?","scene":"Ihr wählt ein Lichtset als gemeinsamen Artikel und einen Sattelüberzug nur für Block.","ask":"Welche Einträge stimmen?","options":["Das Lichtset ist nur in Leer eingeplant.","Das Lichtset gehört je einmal in die Pläne beider Läden.","Der Sattelüberzug belegt automatisch einen Platz in beiden Läden.","Das Licht ist eine örtliche Ergänzung, weil es nur einmal im Ergebnisblatt steht.","Der Sattelüberzug gehört in die Zeile für eine lokale Ergänzung bei Block.","Die zwei Produkte zählen zusammen als zwei Kernartikel."],"answer":[1,4],"why":"Ein Kernartikel erscheint im Angebot beider Läden. Der Sattelüberzug ist hier nur für Aurich gewählt.","hint":"Frage bei jedem Artikel: Für wen steht er in der Liste?","steps":"Ordne ihn in der Liste dem gemeinsamen Kern oder dem konkreten Standort zu.","example":"Ein Schloss, das beide Läden bewerben, ist gemeinsam. Ein nur in Leer gewähltes Werkzeug ist lokal.","id":30,"coreId":0,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M3","M6"]},{"title":"Einen anderen Kern unterscheiden","scene":"Übungsvariante: Zwei Geschäfte werben gemeinsam für Helm, Licht und Schloss. Nur das erste ergänzt einen Sattelüberzug. Nur das zweite ergänzt eine Pumpe.","ask":"Welche Aussagen passen?","options":["Fünf Artikel werden gemeinsam angeboten.","Der Überzug und die Pumpe müssen zusätzlich in beide Läden.","Zum Kern gehören Helm, Licht und Schloss.","Jeder Laden hat zwei verschiedene Ergänzungen.","Der Helm gilt als lokaler Artikel, wenn sich die Kundschaft unterscheidet.","Beide Läden zeigen drei Kernartikel und jeweils ihre eigene Ergänzung."],"answer":[2,5],"why":"Die drei gemeinsam beworbenen Artikel stehen in beiden Geschäften. Überzug und Pumpe wurden je einem Standort zugeordnet.","hint":"Unterscheide gemeinsam beworbene Ware von örtlichen Ergänzungen.","steps":"Zeichne je Laden eine Spalte und gleiche die Einträge ab.","example":"Unterschiedliche Ergänzungen verändern den gemeinsamen Kern nicht.","id":31,"coreId":0,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M3","M6"]},{"title":"Den Katalogtermin lesen","scene":"Im Katalog steht für K70 beim Aktionsbeginn „nein, ab Folgewoche“.","ask":"Was bedeutet der Eintrag?","options":["K70 kommt am ersten Tag sicher an.","Eine Nachfrage im Laden ersetzt die Lieferprüfung.","K70 ist nur im kleineren Laden lieferbar.","K70 steht beim Start nicht bereit.","K70 ist lieferbar, wenn ein Platz frei gehalten wird.","Der Katalog nennt nur den geplanten Preis."],"answer":[3],"why":"„Ab Folgewoche“ liegt nach dem Aktionsstart. Der Termin muss zur geplanten Verkaufswoche passen.","hint":"Wann soll verkauft werden? Wann kommt die Ware?","steps":"Vergleiche den genannten Zeitpunkt mit dem Beginn der Aktion.","example":"Ein Artikel für nächste Woche füllt heute keinen Aktionsplatz.","id":32,"coreId":1,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2"]},{"title":"Hohe Nachfrage trotz Ausfall","scene":"Übungsvariante: Ein neues Flaschenmodell wird zwölfmal nachgefragt, kommt aber nach der Aktion. Ein lieferbares Modell erfüllt denselben Zweck und wurde siebenmal genannt.","ask":"Welche Schritte respektieren Nachfrage und Frist?","options":["Beide Modelle für den Start verbindlich ankündigen.","Den Platz für das verspätete Modell für die ganze Aktion leer halten.","Das lieferbare Modell als Ersatz auf Passung prüfen.","Das verspätete Modell allein wegen der zwölf Nennungen freigeben.","Das verspätete Modell für eine spätere Aktion vormerken.","Sieben Nennungen als Nachweis für sieben sichere Verkäufe nutzen."],"answer":[2,4],"why":"Die Lieferfrist entscheidet, ob die Ware in der laufenden Aktion vorhanden sein kann. Der Bedarf bleibt ein guter Grund, eine verfügbare Alternative oder spätere Aktion zu prüfen.","hint":"Hoher Bedarf und kurze Lieferfrist sind zwei verschiedene Prüfungen.","steps":"Prüfe erst den letzten möglichen Liefertermin und dann die passende Ersatzlösung.","example":"Wenn ein Lichtset zu spät kommt, kann ein anderes passendes und lieferbares Lichtset infrage kommen.","id":33,"coreId":1,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M2"]},{"title":"Was im Angebot fehlt","scene":"Eine Kundenanfrage betrifft das Aufpumpen unterwegs. Auf der Liste steht bereits eine Minipumpe, die zu den angesprochenen Ventilen passt.","ask":"Welche Aussage ist richtig?","options":["Wegen der Anfrage liegt automatisch eine Lücke vor.","Die Minipumpe kann keine Anfrage erfüllen, solange sie keinen gemeinsamen Platz hat.","In dieser Auswahl wird der genannte Bedarf abgedeckt.","Nur der günstigste Artikel kann eine Sortimentslücke schließen.","Der Wunsch fällt aus der Auswertung, sobald ein Artikel im Plan steht.","Ist eine weitere Pumpenfarbe denkbar, besteht zwingend eine Lücke."],"answer":[2],"why":"Eine Lücke besteht, wenn es Nachfrage und dafür kein passendes Angebot gibt. Die geplante, passende Pumpe deckt dieses Bedürfnis ab.","hint":"Prüfe Bedarf und vorhandene Lösung zusammen.","steps":"Frage, ob das bestehende Angebot genau den genannten Zweck erfüllen kann.","example":"Eine passende Lampe kann den Wunsch nach Beleuchtung erfüllen, auch wenn ein anderes Lampenmodell fehlt.","id":34,"coreId":2,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5","M6"]},{"title":"Lücke im Aktionsplan erkennen","scene":"Übungsvariante: In einer Aktionsliste für Leer stehen ein Lichtset, ein Schloss und Taschen. Neun Personen fragten zuletzt nach einer Möglichkeit, eine Trinkflasche am Rahmen zu befestigen. Der passende Halter steht nur im Lieferkatalog.","ask":"Welche Schlüsse sind zulässig?","options":["Der Halter ist schon im Aktionssortiment, weil er im Katalog steht.","Die Auswahl für die Aktion lässt den belegten Wunsch nach einem Flaschenhalter derzeit offen.","Alle regulären Waren des Geschäfts sind in der Aktionsliste abgebildet.","Der Halter kommt als Ergänzung infrage, wenn er lieferbar ist und in den Plan passt.","Das Lichtset beseitigt die Lücke, weil es ebenfalls am Rad befestigt wird.","Neun Anfragen kommen neun verkauften Haltern gleich."],"answer":[1,3],"why":"Der Katalog zeigt eine mögliche Lösung, aber die Liste berücksichtigt sie noch nicht. Die Aussage betrifft die Aktionsauswahl.","hint":"Was steht in der Auswahl und was nur im Katalog?","steps":"Verbinde eine beobachtete Nachfrage mit dem aktuellen Angebot. Prüfe dann eine mögliche Ergänzung.","example":"Für einen Wunsch nach einem Schloss reicht ein Licht in der Liste nicht aus.","id":35,"coreId":2,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5","M6"]},{"title":"Zwei Wünsche zählen","scene":"Eine Kundin fragt im Gespräch nach einer Pumpe und nach einer Rahmentasche. Beide werden im Beratungstagebuch als Wünsche erfasst.","ask":"Welche Zählweise ist richtig?","options":["Zwei Personen werden gezählt.","Die Pumpe erhält eine Nennung.","Gezählt wird ausschließlich der erste Wunsch.","Zwei Verkäufe werden gezählt.","Die Rahmentasche erhält ebenfalls eine Nennung.","Die Wünsche werden gemeinsam als ein neuer Artikel gezählt."],"answer":[1,4],"why":"Im Fall kann ein Gespräch mehrere Anliegen liefern. Jede festgehaltene Nachfrage zählt als eigene Nennung.","hint":"Wie viele Anliegen wurden ausgesprochen?","steps":"Zähle die Wünsche getrennt von den Menschen, die sie genannt haben.","example":"Ein Gespräch über Licht und Klingel liefert zwei Nennungen, auch wenn niemand kauft.","id":36,"coreId":3,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Drei Gespräche auswerten","scene":"Übungsvariante: Person A fragt nach Licht und Schloss. Person B fragt nach Licht. Person C fragt nach Schloss und Pumpe. Alle Wünsche werden erfasst.","ask":"Welche Ergebnisse stimmen?","options":["Die Statistik enthält drei Nennungen.","Die Statistik enthält fünf beratene Personen.","Licht und Schloss kommen jeweils auf zwei Nennungen.","Pumpe und Licht kommen jeweils auf eine Nennung.","Aus den drei Gesprächen ergeben sich fünf Nennungen.","Die Statistik belegt fünf Verkäufe."],"answer":[2,4],"why":"A und C nennen je zwei Wünsche, B einen. Licht und Schloss werden von je zwei Personen angesprochen, die Pumpe einmal.","hint":"Setze pro genanntem Artikel einen Strich.","steps":"Addiere die Striche nach Artikel. Zähle die Gespräche getrennt.","example":"Zwei Gespräche können zusammen drei Warennennungen liefern.","id":37,"coreId":3,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M6"]},{"title":"Eine Kennung eindeutig lesen","scene":"Aus dem Global-Bike-Katalog: L10 LED-Lichtset, S20 Bügelschloss, T30 Rahmentasche.","ask":"Welche Zuordnungen kannst du übernehmen?","options":["T30 LED-Lichtset.","S20 Bügelschloss.","L10 Rahmentasche.","S20 Sattelüberzug.","L10 LED-Lichtset.","T30 Multitool."],"answer":[1,4],"why":"Kennung und Artikelname gehören zur selben Katalogzeile. S20 bezeichnet das Bügelschloss; L10 das Lichtset.","hint":"Vergleiche die ganze Kennung mit dem Namen.","steps":"Lies die Katalogzeile von links nach rechts. Prüfe danach, ob der Eintrag beides richtig wiedergibt.","example":"S20 ist eine Artikelkennung, keine Angabe zur Zahl der Anfragen.","id":38,"coreId":4,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5","M6"]},{"title":"Ähnliche Artikel auseinanderhalten","scene":"Übungsvariante: Im Katalog stehen P51 Standpumpe, P52 Minipumpe und P53 Dämpferpumpe. Im Ergebnisblatt soll die kleine Pumpe für die Fahrt benannt werden.","ask":"Welche beiden Schritte helfen dir, die richtige Pumpe eindeutig einzutragen?","options":["P51 Minipumpe.","„Pumpe“ ohne genaue Bezeichnung.","P52 Minipumpe als ausgewählten Artikel eintragen.","P53 Minipumpe.","Beim Abgleich die Standpumpe P51 als eigenen Artikel getrennt lassen.","P52 und P53 gemeinsam als eine Artikelkennung."],"answer":[2,4],"why":"P52 bezeichnet die Minipumpe für unterwegs. Wenn du P51 und P52 getrennt abgleichst, landet die Standpumpe nicht versehentlich in der Zeile der Minipumpe.","hint":"Ähnliche Nummern können verschiedene Modelle meinen.","steps":"Suche vor dem Eintragen die genaue Bezeichnung und kontrolliere die letzte Ziffer.","example":"P51 und P52 sehen ähnlich aus, nennen im Katalog aber unterschiedliche Artikel.","id":39,"coreId":4,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5","M6"]},{"title":"Katalog zur Passung lesen","scene":"F60 ist ein Flaschenhalter für einen Rahmen mit passenden Gewindeösen. Er ist zum Start lieferbar und braucht einen Platz je Laden.","ask":"Welche Angaben stimmen?","options":["Ein Modell F60 passt ohne Prüfung an jeden Rahmen.","Für den Halter braucht der Rahmen passende Befestigungslöcher mit Gewinde.","Die Kennung F60 nennt seine Nachfragezahl.","Der Artikel kommt erst in der Folgewoche.","Er kann am Start einen Platz im jeweiligen Laden belegen.","F60 ist eine zum Aufpumpen passende Minipumpe."],"answer":[1,4],"why":"Die Katalogzeile beschreibt Artikel, Befestigung, Platzbedarf und Lieferbarkeit. Daraus folgt keine allgemeine Passgarantie.","hint":"Trenne die Passung von der Verfügbarkeit.","steps":"Prüfe, wofür der Artikel gedacht ist, was er benötigt und wann er verfügbar ist.","example":"Ein lieferbarer Flaschenhalter muss zu den Befestigungsmöglichkeiten des einzelnen Fahrrads passen.","id":40,"coreId":5,"reserveNo":1,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Verspätete Ware dokumentieren","scene":"Übungsvariante: Im Katalog steht K71, breite Klingel mit Hebel, erst ab Freitag, ein Platz, nur für Lenker mit dem angegebenen Durchmesser. Die Aktion startet Dienstag.","ask":"Welche Angaben gehören zu einer sauberen Prüfung?","options":["K71 ist beim Start am Dienstag verfügbar.","Die Klingel passt laut Katalog nur zum angegebenen Lenkerdurchmesser.","Alle Lenker verwenden denselben Durchmesser.","Für die geplante Eröffnung ist die Lieferung zu spät.","Sie braucht drei Plätze, da die Lieferung drei Tage später kommt.","K71 braucht einen Platz, wenn der Artikel zu einem erlaubten Termin eingesetzt wird."],"answer":[1,3,5],"why":"Produktmerkmal, Lieferzeit und Platzbedarf sind unterschiedliche Angaben. Die verspätete Lieferung ändert den Platzbedarf nicht.","hint":"Schau in die Spalten für Merkmal, Termin und Platz.","steps":"Stelle die drei Werte getrennt zusammen und vergleiche den Liefertermin mit dem Start.","example":"Ein Artikel kann genau einen Platz benötigen, selbst wenn er für die aktuelle Woche nicht beschafft werden kann.","id":41,"coreId":5,"reserveNo":2,"type":"multi","l":1,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M5"]},{"title":"Den freien Platz berechnen","scene":"Block hat fünf Aktionsplätze, vier davon für den gemeinsamen Kern. Ein Artikel braucht einen Platz.","ask":"Wie viele Plätze bleiben für örtliche Artikel?","options":["Ein Platz.","Zwei Plätze.","Vier Plätze.","Fünf Plätze.","Neun Plätze.","Kein Platz, weil es sich um ein gemeinsames Angebot handelt."],"answer":[0],"why":"5 − 4 = 1. In Aurich bleibt nach den vier Kernartikeln genau ein örtlicher Platz.","hint":"Ziehe vom verfügbaren Platz die schon geplanten Positionen ab.","steps":"Zähle die gemeinsamen Plätze für Aurich einmal vollständig mit.","example":"Bei vier vorhandenen Plätzen und drei Kernartikeln bleibt ein Platz für eine Ergänzung.","id":42,"coreId":6,"reserveNo":1,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Neue Aktion mit Stellgrenze","scene":"Übungsvariante: Geschäft A hat sechs Aktionsplätze, B acht. Jedes Geschäft führt fünf gemeinsame Artikel mit je einem Platz. In B gibt es zusätzlich einen neunten Platz, der für das eigene Sortiment reserviert ist.","ask":"Welche Ergebnisse stimmen?","options":["B kann vier örtliche Artikel aufnehmen.","A hat einen freien Aktionsplatz.","Fünf gemeinsame Artikel brauchen in beiden Geschäften zusammen fünf Plätze.","B hat drei freie Aktionsplätze.","Der neunte Platz zählt zur Aktion, wenn seine Ware lieferbar ist.","Die gemeinsamen Artikel belegen über beide Läden zusammen zehn Plätze."],"answer":[1,3,5],"why":"A rechnet 6 − 5, B rechnet 8 − 5. Der reservierte Platz kommt nicht hinzu. Jeder gemeinsame Artikel steht in beiden Geschäften.","hint":"Rechne pro Laden mit dem freigegebenen Platz.","steps":"Bestimme erst die gemeinsamen Plätze je Laden und danach die Summe über beide Standorte.","example":"Vier Artikel an zwei Standorten ergeben acht belegte Plätze.","id":43,"coreId":6,"reserveNo":2,"type":"multi","l":1,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3"]},{"title":"Warengruppen zusammenfassen","scene":"Übungsvariante: Im Sortiment stehen das LED-Lichtset L10 und ein zweites Fahrradlicht mit eigener Kennung. Beide gehören zur Beleuchtung.","ask":"Was kannst du über diese zwei Artikel sagen?","options":["Sie bilden zwei Warengruppen, weil ihre Nummern verschieden sind.","Beide gehören zur gleichen Warengruppe.","Sie können zwei Stellplätze brauchen, ohne zwei Warengruppen zu bilden.","Der zweite Artikel gehört automatisch zur Warengruppe „Schlösser“.","Zwei Artikel ergeben immer zwei Gruppen.","Eine Warengruppe kann nur eine Kennung enthalten."],"answer":[1,2],"why":"Die Breite zählt die verschiedenen Warengruppen. Zwei Produkte derselben Gruppe können getrennte Positionen belegen.","hint":"Sortiere zuerst nach Art der Ware.","steps":"Zähle anschließend die Gruppen getrennt von den Produkten.","example":"Eine Stablampe und ein LED-Set können beide zur Beleuchtung gehören.","id":44,"coreId":7,"reserveNo":1,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Zwei Sortimente vergleichen","scene":"Übungsvariante: A bietet ein Schloss, eine Tasche und ein Lichtset. B bietet zwei Schlossmodelle an. Alle Artikel stehen auf eigenen Stellplätzen.","ask":"Welche Aussagen zur Breite und Belegung sind richtig?","options":["B ist breiter, weil zwei Modelle derselben Gruppe in der Liste stehen.","A deckt drei unterschiedliche Warengruppen ab.","B nutzt zwei Artikelplätze für eine Warengruppe.","Beide Listen haben dieselbe Sortimentsbreite.","A nutzt weniger Stellplätze als B.","Ein zweites Schloss macht die Liste von B automatisch breiter."],"answer":[1,2],"why":"A hat die Gruppen Schlösser, Taschen und Beleuchtung. B hat zwei Modelle, aber nur die Gruppe Schlösser.","hint":"Produktanzahl und Anzahl der Warenarten sind nicht immer gleich.","steps":"Markiere pro Produkt seine Gruppe und zähle unterschiedliche Gruppen und Stellplätze getrennt.","example":"Drei Farben derselben Klingel erweitern die Auswahl in dieser Gruppe, aber nicht die Warengruppen.","id":45,"coreId":7,"reserveNo":2,"type":"multi","l":1,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M6"]},{"title":"Vorliebe vom Beleg trennen","scene":"Du magst die Rahmentasche. Im Beratungstagebuch sind bei Block neun Fragen zum Verstauen von Kleinteilen, in Leer sieben notiert.","ask":"Welche Aussage nennt einen Nachfragebeleg?","options":["Ich fahre selbst mit einer Rahmentasche.","Die Tasche hat für mich die beste Farbe.","Bei Block stehen neun Fragen zum Verstauen kleiner Dinge im Beratungstagebuch.","Jede Sportlerin kauft eine Tasche.","Ein Teammitglied mag die Tasche ebenfalls.","Die Tasche hat den Code T30."],"answer":[2],"why":"Die Zahl aus dem Beratungstagebuch bezieht sich auf einen Kundenwunsch. Eigene Vorlieben und der Artikelcode belegen die Nachfrage nicht.","hint":"Was beruht auf dokumentierten Kundenfragen?","steps":"Trenne Geschmack, Produktmerkmal und den erfassten Wunsch in drei Gruppen.","example":"Die Kennung kann eine Ware identifizieren; für den Bedarf brauchst du eine andere Information.","id":46,"coreId":8,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3"]},{"title":"Die Lieblingsidee einordnen","scene":"Übungsvariante: Du magst einen Flaschenhalter für Aurich. Dort sprechen zwei Nennungen für den Halter und acht für Licht. Ein Platz ist frei und beide Produkte sind lieferbar.","ask":"Wie gehst du verantwortungsvoll mit deiner Vorliebe um?","options":["Den Halter durchsetzen und die Liste danach ändern.","Die Nennungen weglassen, weil beide Waren verfügbar sind.","Die Vorliebe als Ausgangsidee prüfen und die beobachtete Nachfrage gegenüberstellen.","Acht Nennungen als Beweis für acht Verkäufe angeben.","Prüfen, ob der Bedarf an Licht im übrigen Sortiment bereits erfüllt ist.","Die Lieferung der Artikel als Beweis verwenden, dass beide gleich gut passen."],"answer":[2,4],"why":"Die Nachfrage aus dem betroffenen Laden und der restliche Plan können deine Vorliebe stützen oder entkräften.","hint":"Prüfe, welches neue Problem der freie Platz lösen kann.","steps":"Vergleiche die Bedarfssignale und schau in die geplante Liste, bevor du entscheidest.","example":"Wenn bereits ein passendes Licht im Kern steht, kann ein kleinerer Bedarf für einen örtlichen Platz eine Rolle spielen.","id":47,"coreId":8,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3"]},{"title":"Einen Einwand klären","scene":"Das Team ist für eine Minipumpe in Leer. Eine Person bevorzugt das Multitool. Ihr wollt aus beiden Vorschlägen eine begründete Entscheidung machen.","ask":"Welche Rückfrage hilft zuerst?","options":["Kann die Person später aus der Gruppe ausscheiden?","Wessen Artikel hat die kleinere Kennung?","Wann wurden die Artikelbilder zuletzt geändert?","Welche Anfrage in Leer deckt jeder Vorschlag ab?","Wer hat seine Zeile auf der Liste zuerst ausgefüllt?","Welche Ware finden wir persönlich am schönsten?"],"answer":[3],"why":"Die Frage vergleicht beide Produkte anhand ihrer Aufgabe für dieselbe Kundschaft.","hint":"Was sollen die Vorschläge für denselben Laden lösen?","steps":"Gib beiden Personen Gelegenheit, einen Kundenwunsch zu nennen.","example":"Ein örtlicher Platz kann für Trinkzubehör oder Reparaturbedarf gedacht sein. Beide Zwecke lassen sich mit Nachfrage vergleichen.","id":48,"coreId":9,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Zwei Wünsche, ein Platz","scene":"Übungsvariante: Ein Team bevorzugt für Aurich eine neue Tasche, ein anderes einen Regenschutz. Für beide gibt es passende Artikel mit gleicher Lieferzeit. Nur ein Platz ist verfügbar.","ask":"Welche Schritte führen zu einer tragfähigen Auswahl?","options":["Jede Person füllt unabhängig dieselbe lokale Zeile aus.","Wir vergleichen Kundennennungen und prüfen, ob einer der Wünsche im Kern schon abgedeckt ist.","Wir nehmen grundsätzlich denselben örtlichen Artikel wie in Leer.","Wir entscheiden vor dem Gespräch und tragen später beliebige Zahlen ein.","Wir halten fest, welchen Artikel wir bewusst weglassen und warum.","Wir nutzen im Zweifel beide Artikel auf einem nicht freigegebenen Platz."],"answer":[1,4],"why":"Mit einem Vergleich nach denselben Kriterien lässt sich die Entscheidung für einen Platz begründen. Der Verzicht auf die Alternative wird dokumentiert.","hint":"Vergleicht beide Ideen anhand derselben drei Fragen.","steps":"Prüft Bedarf, vorhandenes Angebot und Umsetzung. Haltet die Einigung anschließend schriftlich fest.","example":"Wenn eine gemeinsame Tasche den Bedarf erfüllt, kann der lokale Platz einen anderen klar belegten Wunsch aufnehmen.","id":49,"coreId":9,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Gleiche Rückfrage an beide Läden","scene":"Sebastian überlegt, L10 als gemeinsamen Artikel für Block und Leer zu empfehlen. Der Artikel ist zum Start verfügbar.","ask":"Welche Fragen helfen im Gespräch mit beiden Standorten?","options":["Wer hat den größeren Laden?","Wofür sucht eure Kundschaft Beleuchtung?","Welcher Artikel hat den kürzeren Produktnamen?","Findet sich in eurem Beratungstagebuch eine passende Nachfrage?","Könnt ihr die Entscheidung ohne eigene Begründung übernehmen?","Könnt ihr stattdessen jeweils einen anderen Artikel als gemeinsamen Artikel anbieten?"],"answer":[1,3],"why":"Ein gemeinsamer Artikel soll zu beiden Läden passen. Gezielte Rückfragen verbinden ihn mit beobachteten Situationen.","hint":"Frag nach dem Kundennutzen an jedem Ort.","steps":"Bitte beide Läden um dasselbe: einen konkreten Bedarf und einen nachvollziehbaren Beleg.","example":"Ein Lichtset kann für den dunklen Arbeitsweg oder für Ausflüge in der Dämmerung relevant sein.","id":50,"coreId":10,"reserveNo":1,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M4"]},{"title":"Ein lokales Anliegen aufnehmen","scene":"Übungsvariante: Beim gemeinsamen Planungsgespräch nennt A Regen auf dem Arbeitsweg, B Probleme mit lockeren Schrauben bei Touren. Ein gemeinsamer Kern wird weiter gewünscht.","ask":"Welche Gesprächsbeiträge bringen die Planung voran?","options":["Den Bedarf des größeren Ladens als Vorgabe für beide übernehmen.","Nachfragen, welcher konkrete Artikel den jeweiligen Wunsch erfüllt.","Den ersten Wunsch, der genannt wird, in alle lokalen Plätze eintragen.","Gemeinsam prüfen, welche anderen Produkte durch die Nachfrage beider Standorte gestützt sind.","Verschiedene lokale Artikel als Beweis ansehen, dass kein gemeinsamer Kern möglich ist.","Die Unterschiede in der Begründung weglassen, damit alle dieselbe Liste erhalten."],"answer":[1,3],"why":"Die Läden können gemeinsame Artikel und unterschiedliche örtliche Bedarfe gleichzeitig haben. Rückfragen machen die Auswahl verständlich.","hint":"Was ist gemeinsam, was braucht eine örtliche Lösung?","steps":"Sammle je Standort einen Bedarf und vergleiche danach, welche Wünsche an beiden Orten vorliegen.","example":"Zwei Läden können ein Schloss gemeinsam führen und je einen anderen Zusatz wählen.","id":51,"coreId":10,"reserveNo":2,"type":"multi","l":1,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["Handlungssituation","M1","M4"]},{"title":"Wenige Nennungen lesen","scene":"Bei Block wurde viermal nach einer leicht bedienbaren Klingel gefragt; in dieser Aufgabe zählt nur, was eine niedrige Nachfragezahl aussagt.","ask":"Was lässt sich daraus lesen?","options":["Der Artikel ist automatisch ausverkauft.","Es gibt belegte Anfragen, auch wenn sie selten sind.","Die vier Einträge garantieren vier verkaufte Klingeln.","Die Zahl kann gestrichen werden, weil sie unter fünf liegt.","Der Wunsch kam bei niemandem vor.","Der Liefertermin folgt direkt aus der Zahl."],"answer":[1],"why":"Wenige Nennungen sind ein kleineres Bedarfssignal. Sie bedeuten weder keinen Bedarf noch sichere Käufe oder eine Lieferzusage.","hint":"Ist vier dasselbe wie null?","steps":"Benenne die beobachtete Nachfrage und lasse Schlussfolgerungen zu Käufen oder Lager getrennt.","example":"Drei Fragen nach einer Tasche können für eine kleine Kundengruppe wichtig sein.","id":52,"coreId":11,"reserveNo":1,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Eine Ferienwoche einordnen","scene":"Übungsvariante: In einer kurzen Ferienwoche wurden drei Fragen zu Regenzubehör gezählt. Im Beratungsteam fällt auf, dass es in dieser Woche kaum geregnet hat.","ask":"Welche Schlüsse sind berechtigt?","options":["An trockenen Tagen gibt es nie Fragen nach Regenschutz.","Auch in dieser Woche wurde Regenzubehör nachgefragt.","Drei Fragen belegen einen festen Jahreswert.","Das Wetter beweist sicher, warum jede Person gefragt hat.","Der beobachtete Zeitraum und das Wetter helfen, die geringe Zahl einzuordnen.","Bei der Planung darf der Standortbezug weggelassen werden."],"answer":[1,4],"why":"Die Zahl zeigt einen beobachteten Bedarf. Wetter und kurze Messdauer begrenzen, was daraus über andere Wochen gefolgert werden kann.","hint":"Achte auf die konkrete Woche.","steps":"Schreibe die Beobachtung mit ihrer Zeitangabe auf. Kennzeichne Erklärungen als Hinweise.","example":"Eine ruhige Ferienwoche kann weniger Beratungen bringen als eine normale Schulwoche.","id":53,"coreId":11,"reserveNo":2,"type":"multi","l":1,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1"]},{"title":"Ein Schloss gemeinsam begründen","scene":"S20 ist lieferbar. Zum sicheren Abstellen wurden bei Block zwölf und in Leer sieben Nennungen erfasst.","ask":"Welche Einträge passen, wenn S20 in den Kern kommt?","options":["S20 steht als gemeinsamer Artikel bei beiden Läden.","Nachfragebeleg nur aus Leer reicht für beide Läden.","S20 passt nur für Block, weil dort die größere Zahl steht.","Für Block stehen 12 und für Leer 7 Nennungen zum sicheren Abstellen in der Begründung.","S20 belegt insgesamt nur einen Stellplatz in beiden Läden zusammen.","Sieben bezeichnet den Lagerbestand für Leer."],"answer":[0,3],"why":"Ein Kernartikel steht in beiden Läden. Die Gründe nennen die beobachtete Nachfrage je Standort.","hint":"Lies die zwei Spalten zum selben Bedarf.","steps":"Übertrage beide Nachfragewerte und verknüpfe sie mit dem einen Produkt.","example":"Ein gemeinsam ausgewähltes Licht bekommt pro Standort einen passenden Beleg.","id":54,"coreId":12,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Ausgewogenen Kern finden","scene":"Übungsvariante: Für den letzten gemeinsamen Platz stehen zwei lieferbare Artikel zur Wahl. Beim Lichtset lauten die Nennungen 10 und 9, beim Flaschenhalter 2 und 15. Alle anderen Plätze sind schon belegt.","ask":"Welche Aussagen stützen eine Auswahl, wenn Bedarf in beiden Läden wichtig ist?","options":["Der Halter passt automatisch besser in beide Läden, weil die 15 der größte Einzelwert sind.","Das Lichtset hat in beiden Läden einen deutlichen Nachfragebeleg.","Die geringere Zahl in einem Laden muss nicht geprüft werden, wenn der andere Laden groß ist.","Der Flaschenhalter ist wegen 2 und 15 eher eine starke örtliche Option für den zweiten Laden.","Zum Kern zählt nur der Artikel mit der höchsten Nachfrage an einem Standort.","Bei einem lieferbaren Artikel genügen Haltung und Vorliebe eines Teams."],"answer":[1,3],"why":"Das Lichtset ist in beiden Läden deutlich gefragt. Beim Halter unterscheidet sich der Bedarf stärker; das kann für eine örtliche Ergänzung sprechen.","hint":"Prüfe die Verteilung, nicht nur die größte Zahl.","steps":"Vergleiche für einen gemeinsamen Platz beide Ladenwerte desselben Artikels und gleiche sie mit der Rolle des Kernsortiments ab.","example":"Acht und neun sind breiter auf zwei Standorte verteilt als zwei und elf.","id":55,"coreId":12,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Aurich direkt vergleichen","scene":"Bei Block wurde der Schutz nasser Sättel elfmal genannt. Der Wunsch nach zusätzlicher Sichtbarkeit wurde sechsmal genannt. R40 und B80 sind lieferbar und noch nicht im Kern. Ein Platz ist frei.","ask":"Welcher Vorschlag folgt der häufigeren Nachfrage in Aurich?","options":["R40 und B80 zusammen auf den einzigen lokalen Platz setzen.","B80 zuerst auswählen, weil die Nachfrage in Leer höher ist.","R40 als örtliche Ergänzung mit elf Nennungen wählen.","R40 auslassen, weil alle Ergänzungen bei beiden Händlern stehen müssen.","B80 wählen, weil sechs Nennungen mehr als elf sind.","K70 auf den Platz setzen, weil jede Lieferung eine Klingel enthalten muss."],"answer":[2],"why":"Der Sattelüberzug geht auf elf Auricher Nennungen ein. Liefern lässt er sich rechtzeitig, und er braucht einen der verfügbaren Plätze.","hint":"Wessen Nachfrage entscheidet über den örtlichen Platz?","steps":"Vergleiche die Werte in der Auricher Spalte und prüfe die Lieferbarkeit.","example":"Ein Bedarf in Leer ist ein Argument für Leer, nicht automatisch für die Auswahl bei Block.","id":56,"coreId":13,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3"]},{"title":"Lokalen Nutzen aus einer Besonderheit ableiten","scene":"Übungsvariante: Für Aurich sind noch eine Tasche und ein Werkzeug lieferbar. Die Beratung hält neun Fragen zum Verstauen von Kleinteilen und fünf zum Nachziehen von Schrauben fest. Das Kernsortiment deckt beide Wünsche noch nicht ab.","ask":"Was stützt die Tasche für den letzten örtlichen Platz?","options":["Das Werkzeug hat im anderen Laden mehr Nennungen.","Die Tasche greift den häufiger genannten offenen Wunsch in Aurich auf.","Beide Artikel sollen gemeinsam je in beiden Läden stehen.","Eine Tasche deckt den Bedarf nach Platz für Schlüssel oder andere Kleinteile ab.","Fünf Nennungen machen das Werkzeug grundsätzlich unverkäuflich.","Bei lokalem Bedarf müssen weder Lieferbarkeit noch Platz geprüft werden."],"answer":[1,3],"why":"Die Tasche passt zum stärker belegten, noch offenen Auricher Bedarf. Das Werkzeug bleibt eine mögliche Alternative mit eigener Nachfrage.","hint":"Achte auf den betrachteten Standort und den Zweck der Ware.","steps":"Vergleiche die beiden offenen Wünsche und verknüpfe den häufigeren mit dem Produkt.","example":"Ein lokaler Bedarf bleibt belegt, auch wenn eine andere Warengruppe in einem zweiten Laden beliebter ist.","id":57,"coreId":13,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3"]},{"title":"Einen zweiten Platz ergänzen","scene":"In Leer ist F60 als erste lokale Ergänzung ausgewählt. Für den zweiten Platz sind P50 mit zwölf und W90 mit acht Nennungen noch offen und lieferbar. Beide stehen nicht im Kern.","ask":"Welche Aussagen führen zu einer begründeten Auswahl nach Nachfrage?","options":["P50 wird mit zwölf Nennungen stärker nachgefragt als W90.","W90 führt, weil es später im Katalog steht.","Der zweite Platz kann beiden Artikeln gleichzeitig zugeordnet werden.","P50 muss in die Liste für Block, weil es auch dort Anfragen gibt.","P50 wäre eine zweite örtliche Position für Leer.","F60 muss erst aus dem Sortiment genommen werden, solange P50 lieferbar ist."],"answer":[0,4],"why":"F60 belegt bereits einen örtlichen Platz. Unter den zwei verbleibenden Optionen hat die Minipumpe den höheren Bedarf in Leer.","hint":"Wie viele Plätze sind noch frei?","steps":"Vergleiche nur die lieferbaren und noch nicht eingeplanten Kandidaten für Leer.","example":"Ein bereits gewählter Artikel braucht keinen zweiten Eintrag, wenn er einmal ausgestellt wird.","id":58,"coreId":14,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Kernartikel und lokale Auswahl abgrenzen","scene":"Übungsvariante: In Leer sind zwei lokale Plätze frei. Der Flaschenhalter ist schon im gemeinsamen Kern, obwohl er 14 Nennungen hat. Von der übrigen lieferbaren Ware haben Pumpe 11, Reflektorband 9 und Werkzeug 8 Nennungen.","ask":"Welche Liste berücksichtigt die zwei stärksten offenen Bedarfe?","options":["Flaschenhalter und Pumpe.","Reflektorband und Werkzeug.","Pumpe und Reflektorband.","Flaschenhalter und Werkzeug.","Alle drei lieferbaren Artikel als lokale Ergänzungen.","Nur das Werkzeug, weil die Pumpe bereits als Bedarf angesprochen wurde."],"answer":[2],"why":"Der Flaschenhalter zählt bereits als Kernartikel. Pumpe und Reflektorband greifen die zwei häufigsten noch offenen Wünsche auf.","hint":"Was steht schon in der gemeinsamen Liste?","steps":"Streiche den bereits berücksichtigten Artikel in der Kandidatenliste und ordne die restlichen drei nach Nachfrage.","example":"Eine erneut aufgeführte Ware blockiert einen Platz für einen neuen Kundenwunsch.","id":59,"coreId":14,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Doppelte Kennung entdecken","scene":"In der Liste steht P50 einmal im gemeinsamen Kern und zusätzlich bei den lokalen Artikeln in Leer. Der Kern ist schon mit vier Artikeln voll.","ask":"Was ist an dieser Stelle zu korrigieren?","options":["Die Minipumpe mit einem zweiten Namen nochmals aufnehmen.","Die beiden Zeilen behalten, weil Leer mehr Platz als Block hat.","P50 nur im Block-Hinweis wiederholen und keine Änderungen zählen.","P50 in Leer nur einmal als Kernartikel führen und die örtliche Position separat besetzen.","Die doppelte Nennung als Beleg für zwei unabhängige Produkte verwenden.","Die Zeile im gemeinsamen Kern löschen und den Kern ohne Ersatz auf drei reduzieren."],"answer":[3],"why":"Ein Kernartikel steht bereits bei beiden Läden. Die örtliche Ergänzung ist eine zusätzliche Artikelposition.","hint":"Ist ein örtlicher Platz für eine Wiederholung gedacht?","steps":"Prüfe die Kennung in der gemeinsamen und örtlichen Liste. Fülle die lokale Position bei Bedarf mit anderem Zubehör.","example":"Ein Schloss im Kern ist in beiden Läden präsent und braucht keine zusätzliche örtliche Aktionsposition.","id":60,"coreId":15,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Zwei Verstöße im Entwurf finden","scene":"Übungsvariante: Der Kern enthält vier lieferbare Artikel. Bei Block stehen zwei örtliche Ergänzungen, bei Leer eine. In Leer ist diese eine Kennung schon im Kern.","ask":"Welche Verbesserungen führen zum vereinbarten Aufbau?","options":["Block soll beide örtlichen Artikel behalten, weil insgesamt drei lokale Zeilen vorhanden sind.","In Aurich muss aus zwei örtlichen Vorschlägen einer ausgewählt werden.","Der gemeinsame Kern muss grundsätzlich aufgeteilt werden.","In Leer werden zwei eigene örtliche Kennungen benötigt, die noch nicht im Kern stehen.","Die Gesamtzahl drei örtliche Zeilen reicht ohne Blick auf die Standorte.","In Leer wird die Doppelung dadurch richtig, dass der Artikel im gleichen Regal steht."],"answer":[1,3],"why":"Die Verteilung gilt pro Geschäft. Ein Kernartikel zählt nicht noch einmal als eigener lokaler Artikel.","hint":"Prüfe jede örtliche Zeile auf den richtigen Laden und doppelte Kennungen.","steps":"Vergleiche die Sollzahl je Laden und kläre danach die eindeutigen Artikelpositionen.","example":"Je ein freier Platz an unterschiedlichen Orten kann nicht ohne Freigabe zu zwei Plätzen an einem der Orte werden.","id":61,"coreId":15,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Gemeinsame Artikel je Laden zählen","scene":"Der Kern hat vier Artikel. Für Block kommt einer dazu, für die Bike Arena zwei. Alle Kennungen sind verschieden.","ask":"Welche Rechenwege gehören in die Platzprüfung?","options":["Block: 4 − 1 = 3 Plätze.","Ladenübergreifend stehen nur sieben Plätze bereit.","Block: 4 + 1 = 5 Plätze.","Leer: 4 + 2 = 6 Plätze.","Leer: 2 + 1 = 3 Plätze.","Der Kern belegt in jedem Laden acht Plätze."],"answer":[2,3],"why":"Die vier gemeinsamen Artikel stehen bei beiden Läden. Dazu kommt je Laden die passende Anzahl an Ergänzungen.","hint":"Addiere pro Laden erst die gemeinsamen und dann die örtlichen Plätze.","steps":"Rechne die beiden Standorte getrennt und vergleiche mit den Vorgaben.","example":"Bei drei Kernartikeln und zwei lokalen Artikeln braucht ein Laden fünf Plätze.","id":62,"coreId":16,"reserveNo":1,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Gesamtbelegung einer neuen Aktion","scene":"Übungsvariante: Zwei Läden bieten drei Kernartikel an. Laden A ergänzt zwei verschiedene Artikel, Laden B drei weitere. Kein lokaler Artikel steht im Kern oder am anderen Standort.","ask":"Welche Kennzahlen stimmen?","options":["Elf verschiedene Artikelkennungen sind erforderlich.","Die Läden nutzen zusammen elf Stellplätze.","Laden B belegt fünf Plätze.","Laden A belegt drei Plätze.","Das Ergebnisblatt enthält acht verschiedene Artikelkennungen.","Die Kernartikel belegen zusammen drei Stellplätze."],"answer":[1,4],"why":"A belegt 3 + 2 = 5 und B 3 + 3 = 6 Stellplätze. Die Kennungen im Blatt zählen 3 + 2 + 3 = 8.","hint":"Unterscheide Stellplatz im Laden und Kennung auf der Liste.","steps":"Zähle für die Belegung den Kern pro Laden. Zähle für die Kennungen jeden unterschiedlichen Artikel einmal.","example":"Ein gemeinsamer Artikel hat einen Code, kann aber in zwei Geschäften je einen Platz belegen.","id":63,"coreId":16,"reserveNo":2,"type":"multi","l":2,"c":3,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M2","M3","M5"]},{"title":"Den Verzicht korrekt formulieren","scene":"In Aurich passt R40 besonders gut, weil elf Anfragen zu nassen Sätteln vorliegen. F60 ist lieferbar und wurde viermal nachgefragt. Es steht nur ein örtlicher Platz zur Verfügung.","ask":"Welche Aussage erklärt den Verzicht auf F60?","options":["F60 ist nicht lieferbar.","F60 wurde in Aurich gar nicht nachgefragt.","F60 hat eine Kennung, also passt er nicht.","Der einzige örtliche Platz geht an den stärker belegten Sattelschutz.","Der Verzicht beweist, dass niemand einen Flaschenhalter kauft.","R40 und F60 sind beide lokale Ergänzungen auf dem gleichen Platz."],"answer":[3],"why":"Der Verzicht ergibt sich aus knappen Plätzen und dem stärkeren Beleg für R40. F60 bleibt grundsätzlich verfügbar und nachgefragt.","hint":"Benenne den sachlichen Grund für den Vorrang.","steps":"Erkläre, welches Produkt trotz guter Eignung aus Platzgründen zurücksteht.","example":"„Lieferbar, aber hinter einem stärkeren Bedarf eingeordnet“ grenzt eine Auswahl von einem Lieferproblem ab.","id":64,"coreId":17,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Nicht jede verfügbare Ware auswählen","scene":"Übungsvariante: Für Leer sind alle Plätze besetzt. Ein lieferbares Werkzeug mit acht Nennungen steht noch nicht in der Liste. Die zwei örtlichen Plätze decken mit Pumpe und Halter elf und zwölf Nennungen ab.","ask":"Welche Begründungen bleiben fair und überprüfbar?","options":["Niemand in Leer braucht ein Werkzeug.","Das Werkzeug ist lieferbar und hat einen belegten Bedarf, für die knappen Plätze haben die beiden anderen Produkte mehr Nennungen.","Acht Nennungen beweisen, dass das Werkzeug zu spät kommt.","Die Katalogkennung entscheidet unabhängig von Kundendaten.","Wenn sich später ein Platz eröffnet, ist das Werkzeug eine begründete Alternative.","Das Werkzeug muss zusätzlich in den reservierten Ladenplatz, weil jede lieferbare Ware ausgewählt wird."],"answer":[1,4],"why":"Die Aufnahme ist eine Abwägung, keine Aussage, dass andere Waren wertlos sind. Die vorliegenden Belege erklären die Reihenfolge in dieser Liste.","hint":"Trenne Nachfrage, Lieferbarkeit und Priorität.","steps":"Nenne die Nachfrage der ausgeschlossenen Ware und vergleiche mit den gewählten Waren je Laden.","example":"Eine schwächer nachgefragte Ware kann später aufgenommen werden, wenn Platz und Bedarf dazu passen.","id":65,"coreId":17,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Einen Wunsch noch einmal prüfen","scene":"Du möchtest für Leer P50 als lokalen Artikel. Eine Teamkollegin zeigt dir, dass P50 bereits im Kern steht.","ask":"Welcher Schritt hilft bei der Überarbeitung?","options":["P50 nochmals eintragen und zu einer anderen Warengruppe erklären.","P50 aus dem Kern entfernen, ohne den gemeinsamen Platz neu zu planen.","Die örtliche Position für einen noch nicht abgedeckten Wunsch prüfen.","Den Hinweis der Kollegin weglassen, wenn er die Entscheidung erschwert.","Die Kennung des zweiten Eintrags ändern, obwohl es dieselbe Ware ist.","Nur die farbliche Gestaltung der Liste ändern."],"answer":[2],"why":"Der Pumpenbedarf wird durch den Kern bereits berücksichtigt. Die lokale Ergänzung kann einen weiteren Bedarf abdecken.","hint":"Prüfe, ob dein Ziel bereits erreicht wird.","steps":"Schau zuerst in den Kern, danach in die Nachfrage zu noch offenen Artikeln.","example":"Eine im Kern geplante Rahmentasche steht schon in beiden Läden.","id":66,"coreId":18,"reserveNo":1,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Auf eine neue Liefermeldung reagieren","scene":"Übungsvariante: Du hast für Aurich einen Sattelüberzug ausgesucht. Die Logistik meldet, dass er erst nach der Aktion kommt. Ein Reflektorband wäre zum Start verfügbar. Ob es zu einem offenen Kundenwunsch in Aurich passt, ist noch unklar.","ask":"Woran zeigt sich ein begründetes Umdenken?","options":["Ich lasse den Überzug im Plan und verspreche die rechtzeitige Lieferung.","Ich erkläre die Nachfrage nach Sattelschutz für widerlegt.","Ich prüfe den lieferbaren Alternativartikel mit der Nachfrage in Aurich.","Ich übernehme ungeprüft den ersten Vorschlag aus Leer.","Ich halte fest, dass die Liefermeldung meinen ursprünglichen Plan verändert hat.","Ich plane beide Artikel als örtliche Ergänzungen auf dem einzigen Platz."],"answer":[2,4],"why":"Der frühere Kundenbeleg bleibt gültig. Die Auswahl muss trotzdem auf den lieferbaren Zeitraum reagieren und die Alternative eigenständig begründen.","hint":"Welche Information hat sich geändert?","steps":"Prüfe die bisherige Entscheidung unter der neuen Bedingung und begründe jede Ersatzware mit ihrem eigenen Bedarf.","example":"Liefert ein Hersteller später, ändert sich der verfügbare Artikel, nicht die Zahl früherer Fragen.","id":67,"coreId":18,"reserveNo":2,"type":"multi","l":2,"c":1,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Vergleichsregeln vereinbaren","scene":"Im Team stehen ein Lichtset und ein Schloss zur Wahl für einen gemeinsamen Platz. Beide sind lieferbar.","ask":"Welche gemeinsame Prüfung ist diskussionsfähig?","options":["Für beide Waren die Nachfrage bei Block und in Leer vergleichen.","Den höchsten Einzelwert aufnehmen und den anderen Laden unberücksichtigt lassen.","Immer nach der zuerst genannten Idee entscheiden.","Den bereits geplanten Kern ansehen und prüfen, welchen Bedarf beide Varianten zusätzlich abdecken.","Eine Ware für Block und die andere für Leer als einen gemeinsamen Artikel zählen.","Die Produktnamen nach Länge vergleichen."],"answer":[0,3],"why":"Eine gemeinsame Position muss für beide Läden begründet werden und in den vorhandenen Kern passen.","hint":"Lege dieselben Kriterien für beide Artikel fest.","steps":"Vergleiche Niederlassungen getrennt, zusammen mit der bereits ausgewählten Ware.","example":"Wenn eine Beleuchtungsart vorhanden ist, kann ein anderer gemeinsamer Bedarf Vorrang haben.","id":68,"coreId":19,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Uneinige Vorschläge zusammenführen","scene":"Übungsvariante: Für einen Kernplatz ist eine Tasche an beiden Standorten stärker nachgefragt. Ein Teammitglied bevorzugt ein Werkzeug, weil es einen bisher nicht berücksichtigten Kaufanlass abdeckt.","ask":"Welche Schritte ermöglichen eine nachvollziehbare Entscheidung?","options":["Die Tasche allein wegen des höheren Werts sofort freigeben.","Den stärkeren Bedarf der Tasche und den neuen Kaufanlass des Werkzeugs getrennt darstellen.","Das Werkzeug nur als gemeinsames Produkt bezeichnen, obwohl es nur einer führen soll.","Vereinbaren, welcher Zweck für den letzten Kernplatz wichtiger ist, und den Grund aufschreiben.","Die unterschiedlichen Argumente in der Liste nicht erwähnen.","Nur den persönlich vertrauten Kaufanlass berücksichtigen."],"answer":[1,3],"why":"Häufigkeit und zusätzlicher Nutzen sind verschiedene Kriterien. Ein klarer Vergleich macht sichtbar, warum ein Artikel Vorrang erhält.","hint":"Welche zwei Gründe stehen sich gegenüber?","steps":"Hört beide Positionen an und begründet gemeinsam, welches Kriterium in diesem Fall den Ausschlag gibt.","example":"Ein bereits versorgter Bedarf kann trotz hoher Nachfrage anders gewichtet werden als eine offene Lücke.","id":69,"coreId":19,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Einen nachvollziehbaren Beleg verlangen","scene":"In einer anderen Liste steht „P50 für Leer, weil passt“. Der Katalog nennt eine Minipumpe; zwölf Nennungen betreffen in Leer das Aufpumpen unterwegs.","ask":"Welche Rückmeldung hilft der Gruppe?","options":["Schreibt einfach „passt gut“.","Übernehmt die Auricher Nennungen, weil dort auch Räder genutzt werden.","Ergänzt den Bezug zu den zwölf Nennungen für das Aufpumpen unterwegs in Leer.","Streicht P50 und nutzt nur den Namen „Zubehör“.","Begründet P50 mit der Zahl der fünf Plätze in Aurich.","Schreibt dazu, ob die Pumpe zum Start lieferbar ist."],"answer":[2,5],"why":"Eine gute Rückmeldung nennt die fehlende Fallangabe und das Kriterium zur Umsetzung. „Passt“ allein bleibt unklar.","hint":"Welche Angaben lassen sich in M1 und M2 prüfen?","steps":"Nenne den genauen Bedarf im richtigen Laden und prüfe dann die Lieferzeit.","example":"Statt „gute Tasche“ lässt sich „neun Fragen zum Verstauen kleiner Dinge“ als Nachfragebeleg prüfen.","id":70,"coreId":20,"reserveNo":1,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Zwei unklare Zeilen kommentieren","scene":"Übungsvariante: In einer Liste steht „L10 gemeinsam, 13 Nennungen“ und „W90 weggelassen, weil unnötig“. Für Licht sind in Aurich 13 und in Leer 8 Nennungen erfasst. W90 ist lieferbar; es gibt Nachfrage zum Nachziehen von Schrauben.","ask":"Welche Hinweise verbessern die Liste?","options":["Das Wort „unnötig“ für W90 mit einem größeren Schriftgrad hervorheben.","Den zweiten Standort und seine acht Nennungen für den Kernartikel ergänzen.","Die 13 Nennungen ohne Prüfung auf beide Läden übertragen.","Bei W90 angeben, welcher andere Bedarf oder welche Platzgrenze bei der Auswahl ausschlaggebend war.","Die Nachfrage nach Werkzeug aus dem Beratungstagebuch ohne Grund entfernen.","Für Licht nur die Artikelkennung im Ergebnis stehen lassen."],"answer":[1,3],"why":"Ein Kernartikel braucht eine Begründung für beide Läden. Der Verzicht auf W90 sollte mit Alternativen oder Grenzen begründet werden, obwohl der Bedarf belegt ist.","hint":"Gibt die Liste pro Standort und pro Verzicht einen überprüfbaren Grund?","steps":"Markiere die fehlende Stelle in der Kernzeile und schlage eine sachliche Formulierung zur Auswahl vor.","example":"Eine faire Rückmeldung kann einen lieferbaren Artikel als Option anerkennen und trotzdem einen anderen empfehlen.","id":71,"coreId":20,"reserveNo":2,"type":"multi","l":2,"c":2,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Artikel in die passende Zeile setzen","scene":"Die Rahmentasche T30 wird als Kernartikel eingeplant. Es gibt neun Nennungen bei Block und sieben in Leer zum Verstauen kleiner Dinge. Die Ware ist zum Start lieferbar.","ask":"Welche Angaben gehören ins Ergebnisblatt?","options":["T30 Rahmentasche nur als örtliche Ergänzung bei Block.","T30 Rahmentasche, gemeinsamer Kern, beide Läden.","Als Begründung die neun und sieben passenden Nennungen mit jeweiligem Standort.","Keine Lieferangabe, weil erst der Kundenwunsch zählt.","Den Eintrag auf „Kernartikel“ kürzen und die Kennung weglassen.","Zum Start lieferbar laut Katalog."],"answer":[1,2,5],"why":"Der Eintrag bezeichnet Produkt, Bereich, beide Ladenbelege und Lieferbarkeit. Dadurch kann Jan ihn sachlich prüfen.","hint":"Welche Spalten braucht die Ergebniszeile?","steps":"Ergänze Namen und Kennung, die Funktion im Sortiment und die passenden Nachweise.","example":"Eine vollständige Kernzeile muss für beide Standorte verständlich sein.","id":72,"coreId":21,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Eine fehlende lokale Zeile ergänzen","scene":"Übungsvariante: Für Block ist als örtliche Ergänzung ein wetterfester Taschenüberzug D21 vorgesehen. Sechs Nachfragen bemängeln nasse Taschen. Der Katalog nennt „startklar, 1 Platz“.","ask":"Welche Einträge dokumentieren die Entscheidung?","options":["D21 gemeinsam, ohne Angabe zum Laden.","D21 wetterfester Taschenüberzug, lokale Ergänzung für Block.","Lagerstand „sechs“, weil sechs Menschen gefragt haben.","Sechs Nachfragen in Aurich zu nassen Taschen als Beleg.","Zum Start lieferbar, ein Platz bei Block.","Aus den Nachfragen sechs sichere Verkäufe eintragen."],"answer":[1,3,4],"why":"Die lokale Zeile zeigt Ware, Ort, Bedarf und Umsetzung. Aus den Anfragen folgt keine Verkaufszahl.","hint":"Trenne die Angaben aus Beratung und Katalog.","steps":"Stelle die Zeile aus Produktkennung, Zielort, Beleg und Bedingungen zusammen.","example":"Eine Begründung wird prüfbar, wenn die Kennung eindeutig und die Nachfrage dem richtigen Laden zugeordnet ist.","id":73,"coreId":21,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M5"]},{"title":"Standortspalten abstimmen","scene":"Vier Artikel sind für beide Läden vorgesehen. Deine Tabelle zählt einen davon ausschließlich als örtlichen Artikel bei Block, weil in Leer das Feld leer ist.","ask":"Was muss in der Tabelle korrigiert werden?","options":["Die Rolle des Produkts aus der fehlenden Markierung ableiten und es örtlich lassen.","Für den betreffenden Kernartikel bei beiden Läden eine belegte Position markieren.","Die Standortsumme erneut prüfen.","Den gleichen Artikel mit einer neuen Kennung für Leer eintragen.","Die Summen für beide Läden zusammenfassen und die falsche Spalte weglassen.","Den Kernartikel in Leer nur als örtliche Ergänzung zählen."],"answer":[1,2],"why":"Die gemeinsamen Felder müssen bei beiden Läden gesetzt sein. Eine Neuberechnung zeigt, ob die Zahl pro Standort danach passt.","hint":"Was weißt du über den Artikel aus der Planung?","steps":"Korrigiere die Zuordnung in beiden Spalten und rechne pro Laden neu.","example":"Ein fehlendes Häkchen kann eine viel kleinere Belegung anzeigen, als der Plan wirklich vorsieht.","id":74,"coreId":22,"reserveNo":1,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Formel und Belegung prüfen","scene":"Übungsvariante: In der Spalte für Leer stehen vier gemeinsame und zwei örtliche Markierungen. Die Summenformel zählt nur die vier gemeinsamen Zeilen. Sie zeigt „4 von 6“.","ask":"Welche Prüfungen sind sinnvoll?","options":["Zwei neue Artikel hinzufügen, weil die Summe 4 zeigt.","Den Bereich der Formel so erweitern, dass die beiden örtlichen Zeilen mitzählen.","Die örtlichen Markierungen aus der Tabelle löschen.","Die vier gemeinsamen Zeilen fälschlich doppelt zählen.","Das Ergebnis mit 4 + 2 = 6 vergleichen.","Die Kapazität von sechs auf vier absenken, ohne die Vorgabe zu ändern."],"answer":[1,4],"why":"Die Markierungen sind vollständig, aber die Formel erfasst sie nicht alle. Mit den lokalen Markierungen ergibt die richtige Summe sechs.","hint":"Prüfe die Eingaben und die Formel getrennt.","steps":"Kontrolliere, welche Tabellenzeilen in der Berechnung enthalten sind, und vergleiche mit der Rechnung von Hand.","example":"Wenn eine Formel einen Bereich auslässt, sind korrekte Einzelwerte allein keine Garantie für die richtige Summe.","id":75,"coreId":22,"reserveNo":2,"type":"multi","l":2,"c":4,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M3","M5"]},{"title":"Liefergrenze vor Freigabe prüfen","scene":"Die Plätze stimmen: vier gemeinsame Artikel, eine Ergänzung für Aurich, zwei für Leer. Einer der örtlichen Artikel in Aurich ist beim Start nicht lieferbar.","ask":"Welche Entscheidung passt zur bestehenden Planung?","options":["Die Liste unverändert freigeben, da die Anzahl richtig ist.","Den verspäteten Artikel als Kernartikel umbenennen, damit er rechtzeitig kommt.","Die Freigabe für die vorgeschlagene Zusammensetzung erst erteilen, wenn der örtliche Artikel ersetzt und geprüft ist.","Die Lieferbarkeit des fehlenden Artikels im Ergebnisblatt als „ja“ markieren.","Ohne Kundenbeleg irgendeinen Katalogartikel für den Platz übernehmen.","Die örtliche Position in beiden Läden streichen."],"answer":[2],"why":"Richtige Platzbelegung allein reicht nicht. Eine lieferbare und begründete Alternative muss die örtliche Position erfüllen.","hint":"Welche Vorgabe bleibt trotz richtiger Summe offen?","steps":"Prüfe bei jedem Eintrag, ob Ware und Belastbarkeit der Begründung zum Aktionsstart passen.","example":"Ein rechtzeitig lieferbarer Artikel kann einen frei werdenden Platz füllen, wenn er auch zum Bedarf passt.","id":76,"coreId":23,"reserveNo":1,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]},{"title":"Zwei verschiedene Fehler vor Freigabe","scene":"Übungsvariante: Entwurf A hat vier gemeinsame lieferbare Artikel, eine lieferbare Ergänzung bei Block und drei bei Leer. Entwurf B hat vier gemeinsame Artikel, einen örtlichen in Aurich und zwei in Leer. Ein gemeinsamer Artikel in B kommt erst nach dem Start.","ask":"Welche Aussagen gehören in Jans Prüfung?","options":["A passt, weil alle Artikel sofort verfügbar sind.","A überschreitet die für Leer vorgesehene Zahl der lokalen Plätze.","B passt, weil ein verspäteter gemeinsamer Artikel nicht für örtliche Positionen zählt.","B muss vor Freigabe einen lieferbaren, für beide Läden begründeten Ersatz prüfen.","Die Zahl der örtlichen Plätze in Aurich stimmt in keinem Entwurf.","A und B können ohne weitere Nachfrageprüfung freigegeben werden."],"answer":[1,3],"why":"A scheitert an der örtlichen Platzgrenze, B an der Lieferfrist für einen Kernartikel. Vor einer Freigabe braucht die bereinigte Liste außerdem Nachfragebelege.","hint":"Prüfe jeden Plan nach denselben Bedingungen.","steps":"Zähle zuerst die lokalen Plätze, prüfe dann die Artikel einzeln auf Lieferbarkeit und Nachfrage.","example":"Verschiedene Entwürfe können an verschiedenen Vorgaben scheitern, selbst wenn jeder einen Teil korrekt löst.","id":77,"coreId":23,"reserveNo":2,"type":"multi","l":2,"c":0,"caseLabel":"LS 6.2 · Ein gemeinsames Sortiment mit lokalen Ergänzungen zusammenstellen","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen.","sourceRefs":["M1","M2","M3","M5"]}];
